// كتاب الطهارة — القسم الأول: باب فضل الوضوء وما بعده (ص5–...)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب فضل الوضوء (ص5–15)`,
    items: [
      { q: `معنى قوله ﷺ «الطهور شطر الإيمان»`, p: `7–8`,
        n: `اختُلف في معنى قوله ﷺ «الطهور شطر الإيمان»: فقيل: معناه أن الأجر فيه ينتهي تضعيفه إلى نصف أجر الإيمان. وقيل: معناه أن الإيمان يجبُّ ما قبله من الخطايا وكذلك الوضوء، لأن الوضوء لا يصح إلا مع الإيمان فصار لتوقفه على الإيمان في معنى الشطر. وقيل: المراد بالإيمان هنا الصلاة كما قال الله تعالى: ﴿وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ﴾، والطهارة شرط في صحة الصلاة فصارت كالشطر، وليس يلزم في الشطر أن يكون نصفًا حقيقيًّا، وهذا القول أقرب الأقوال. ويحتمل أن يكون معناه أن الإيمان تصديق بالقلب وانقياد بالظاهر، وهما شطران للإيمان، والطهارة متضمنة الصلاة فهي انقياد في الظاهر.`,
        o: `قيل: ينتهي تضعيف أجره إلى نصف أجر الإيمان. وقيل: الإيمان يجبُّ ما قبله وكذلك الوضوء فصار في معنى الشطر. وقيل: الإيمان تصديق وانقياد، والطهارة المتضمنة للصلاة انقياد في الظاهر.`,
        s: `القول بأن المراد بالإيمان هنا الصلاة كلام قوي، فمعنى «الطهور شطر الإيمان» أي: شطر الصلاة. وهناك معانٍ أخرى مبنية على التفسير بالإشارة: فالطهور هو التنزه والتخلص من الأدران، ولما كان الإيمان فعلًا وتركًا كان التنزه عن النقائص والمنكرات والمحرمات والتطهر منها (تطهير القلب وتطهير الجوارح) نصفَ الإيمان. وهذا معنى حسن؛ لأن الإيمان يشمل فعل الواجبات وترك المحرمات بالقلب واللسان والجوارح، فتنزُّهه عن الأدران الظاهرة والباطنة هو شطر الإيمان، ويبقى الشطر الآخر وهو فعل المأمورات (فترك المحظور المنهي عنه شطر الإيمان).`,
        f: [
          `(ص5) على قول الخليل والأصمعي وغيرهما «إنه بالفتح فيهما»: بمعنى أن [الوَضوء والطَّهور] الاثنين لفظ مشترك يُطلق على المعنيين: (المصدر والماء).`,
          `(ص5) على قول صاحب المطالع «وحُكي الضم فيهما جميعًا»: وهذا هو الوجه الثاني، [الوُضوء والطُّهور] أيضًا لهما المعنيان: (الفعل والماء).`,
          `(ص5) على قوله «يجوز بضم الغين وفتحها لغتان مشهورتان»: فيكون [الغَسل والغُسل] إذا أُريد به الفعل. وعلى قول بعضهم «إن كان مصدرًا لغسلتُ فهو بالفتح»: ومنه [غَسل النجاسة] فلا تقول [غُسل النجاسة].`,
          `(ص6) على قوله «غُسل الجمعة مسنون»: ويمكن أن يُقال فيه [غَسل الجمعة مسنون] على الوجه الأول، فإنه قال (لغتان مشهورتان)، وهذا على الفعل الذي هو المصدر. وعلى قوله «الغُسل من الجنابة واجب»: هذا اللفظ هو المشهور أكثر.`,
          `(ص6) على قوله «بعض من صنَّف في لحن الفقهاء»: من ألَّف في الخطأ الذي يقع فيه كثير من الفقهاء لغةً، فاللحن معناه الخطأ في اللغة. وعلى قوله «بل الذي قالوه صواب كما ذكرناه»: وكما وردت به الأحاديث الصحيحة وكما ذكر أهل اللغة.`,
          `(ص6) على قوله «هذا الإسناد مما تكلم فيه الدارقطني وغيره»: أي أنه أحد ما استدركه الدارقطني من جهة الإسناد مع صحة الحديث بلا شك.`,
          `(ص6–7) على جواب النووي عن استدراك الدارقطني: لأن الراوي الذي سقط هو ثقة فلا يضر في صحة الحديث، وليس كل استدراكات الدارقطني طعنًا في الحديث، فقد يكون خلل في الإسناد مع صحة المتن، فهم يأخذون على مسلم هذا. ولا شك أن بعض الرواة قد روى أولًا الإسناد نازلًا ثم يعلو له الإسناد بذهابه للشخص نفسه، وخصوصًا مع المعاصرة بإمكانية السماع واللقاء، فيرويه عمن روى عنه، فيسمعه بعض الناس عن الراوي الأول. مثلًا: أبو سلام لم يكن سمعه أولًا من أبي مالك، وسمعه أولًا من عبد الرحمن بن غنم عن أبي مالك، ورواه هكذا، والرواة رووه هكذا، ثم ذهب إليه فسمع منه فحدَّث به، فلا مانع من هذا الأمر. أو أحيانًا نسي، فمثلًا قد كان متأكدًا من أنه سمعه من الراوي الذي هو عن عبد الرحمن بن غنم عن أبي مالك، والمرة الثانية تذكر أنه قد سمعه منه، فلا مانع من هذا. وبالتالي ليس وجود إسناد فيه راوٍ يطعن في الإسناد الآخر. هذا خلاصة شرح كلام النووي.`,
          `(ص8) على قوله ﷺ «والحمد لله تملأ الميزان» (في الميزان): بأن هناك ميزانًا توزن فيه أعمال العباد، وهذا الحديث يدل على أن نفس الأعمال أو الأقوال يوضع في الميزان، فهو أحد أدلة أن الموزون هو العمل نفسه. وقد وردت الأدلة على تعدد الموزون: إما العمل، وإما ثواب العمل [فقد جعلهما كثير من العلماء متلازمين (شيئًا واحدًا)]، وإما الشخص نفسه [فكما قال ﷺ: «إنه ليأتي الرجل العظيم السمين يوم القيامة لا يزن عند الله جناح بعوضة، اقرؤوا: ﴿فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾»، وقال ﷺ عن ساقَي ابن مسعود: «مِمَّ تضحكون؟» قالوا: يا نبي الله من دقة ساقيه، فقال: «والذي نفسي بيده لهما أثقل في الميزان من أُحد»]، وإما صحائف الأعمال [فيدل عليه حديث البطاقة: «فيُنشر له تسعة وتسعون سجلًّا كل سجل مدَّ البصر، ثم يقول الله: هل تنكر من هذا شيئًا؟ ... فتخرج له بطاقة فيها: أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله ... فتوضع السجلات في كفة والبطاقة في كفة، فطاشت السجلات وثقلت البطاقة، ولا يثقل مع اسم الله شيء»]، وهذا نص في أن الموزون هو صحائف الأعمال، ولا مانع من وقوع كل ذلك معًا أو وقوع واحد منها. والميزان أحد ما يؤمن به من أمور الآخرة، وهو داخل في الإيمان باليوم الآخر، وكيفيته لا يعلمها إلا الله، وله كفتان كما دل عليه حديث البطاقة.`,
          `(ص8) على قوله «فالأول ضمير مؤنثتين غائبتين، والثاني ضمير هذه الجملة من الكلام»: أي أن (سبحان الله والحمد لله) هذه الجملة هي التي (تملأ) ما بين السماوات والأرض، وأما (تملآن) أي أن كل كلمة من (سبحان الله) و(الحمد لله) كلٌّ منهما تملأ.`,
          `(ص9) على قول صاحب التحرير «يجوز تملآن بالتأنيث والتذكير جميعًا»: (تملآن) تأنيث و(يملآن) تذكير، فلو قلنا (وسبحان الله والحمد لله تملآن) فكل منهما ذِكر، فهما ذِكران، فيمكن أن تملآ. وأما (يملأ) [وأما يملأ فمذكر على إرادة الذكر]: (وسبحان الله والحمد لله يملأ ما بين السماوات والأرض) أي هذا ذكر يملأ ثوابه ما بين السماوات والأرض.`,
          `(ص9–11) على قوله «وسبب عظم فضلهما ما اشتملتا عليه من التنزيه لله تعالى بقوله سبحان الله، والتفويض والافتقار إلى الله تعالى بقوله الحمد لله»: سبحان الله: توحيد وتنزيه الله عن كل نقص، فهو يشمل التنزيه عن الشرك في ربوبيته وألوهيته، وتنزيهه عن الند والكفء والمثل في أسمائه وصفاته، وتنزيهه عن صفات النقائص كلها عما يقوله الظالمون علوًّا كبيرًا، فيُنزَّه عن الصاحبة والولد والعجز والضعف والمرض والموت وسائر ما نسبه الكفار لله تعالى. وأما الحمد لله فهو أفضل الدعاء كما قال ﷺ: «أفضل الذكر لا إله إلا الله، وأفضل الدعاء الحمد لله» (ابن ماجه). وحقيقتها الثناء على الله ﷻ للكمال وللنعم، للحسن والإحسان، للكمال الذاتي الذي يتصف به ربنا ﷻ لكماله في ذاته وصفاته وأسمائه وأفعاله؛ فكل أسمائه حسنى وكل صفاته عُلا، وكل أفعاله عدل وحكمة ﷻ، وهي في موضعها وموقعها يستحق الحمد عليها، فيُحمد ﷻ في الأولى والآخرة، على المحبوب والمكروه ﷻ، حتى يُحمد على ما قدَّره من وجود ما لا يحبه، لأنه جعل من وراء ذلك الحكمة والمصلحة والخير الذي لا يحيط به أحد من العباد علمًا. والثناء على الله ﷻ بنعمه على عباده بإحسانه إليهم (الحمد لله) على النعم، والتي أعظمها النعم الباطنة: من الإسلام والإيمان والإحسان، ونعمة الالتزام بالدين والسنة، ونعمة القرآن وبعثة النبي ﷺ، ونعمة الهداية إلى منهج أهل الحق والصراط المستقيم منهج أهل السنة والجماعة، فهذه أعظم النعم لأنها تؤدي إلى السعادة الأبدية. والنعم الظاهرة الأخرى من الحياة وما أنعم الله على عباده فيها من سمع وبصر ويد ورجل، وسلامة بدن وصحة وعافية، وأهل ومال وولد وغير ذلك من أنواع النعم التي لو عدَّها الإنسان لا يحصيها، فضلًا عن النعم العامة التي لا يشكر الله عليها إلا القليل من الخلق: كنعم الشمس والقمر والأنهار والليل والنهار؛ هذه النعم لكثرة تكرارها على العباد عدُّوها من الأمور المعتادة، ولو غاب عنهم شيء منها لأدركوا كيف هي عظيمة؛ فيوم أن جاءت سحابة سوداء أظلمت على الناس عدة ساعات، انظروا كم الرعب الذي حصل للناس، فقالوا: يومها الدنيا قد خربت! ولو أن الليل صار سرمدًا أو النهار صار سرمدًا، كل من هذه النعم لا يشكر الله عليها إلا القليل من خلقه. وكذلك نعمة الأنهار ونعمة السماء والأرض، فهذه نعم عظيمة لو قدَّر الإنسان زوالها لشكر الله عليها؛ سكون هذه الأرض ﴿أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا * وَالْجِبَالَ أَوْتَادًا﴾، فلحظة الزلزال الناس يعرفون عظمة هذه النعمة وأننا نسير على أرض ساكنة لا تهتز، ولأنها نعمة مستمرة، واضطراب الأرض لحظات فقط ثوانٍ معدودة يحدث فيها خراب الدنيا، فأكثر الناس لا يتذكرون هذه النعمة إلا عندما تغيب. ونعمة الهواء الذي يتنفسه الناس، فإذا اختنق في نفق أو حجرة فعندها يشعروا بهذه النعم؛ وفي الحقيقة في كل لحظة هذه نعم متجددة، ففي كل دقيقة هناك زفير وشهيق عشرون مرة، كل منهم نعمة لا يقدر بقدر يدركها بقدر من حُرم منها. والإنسان إذا اعترف بنعم الله بقلبه واعترف بعجزه عن شكرها وعدم استطاعته عد هذه النعم وعدم إدراك حقيقة الواحدة منها؛ فكل نعمة إذا تأملت فيها ستجدها متضمنة للعديد من النعم، لذلك قالوا: (مع العجز عن شكرها والوقوف على حدها). فكما قلنا نعمة الأنهار فهي تجري تأتي من آلاف الأميال وتكون مياهًا نقية ليس ملحًا أجاجًا، عذبة ميسرة سهلة تصل إلينا يتنفع بها العباد في أنفسهم وزروعهم وبهائمهم؛ فهذه الشربة التي وصلت إليك نقية لو حرمتها لهلكت، فإذا نزلت إلى المعدة وجدت فيها مستقرها وامتصاصها وتدبرها داخل جسم الإنسان حتى تصل إلى مواضعها فتروي عطش الإنسان، فلو حُرم الإنسان من نعمة الري فهذه نعمة أخرى بمفردها؛ فيشرب الإنسان الشربة فيجد الري، بخلاف إنسان يشرب ولا يجد الري، فلو إنسان عنده مرض السكر يشرب ماءً كثيرًا ولا يشعر بالري لأن عنده مرضًا داخليًّا يجعله يشعر بمزيد من الحاجة للشراب. وهناك أُناس تعجز عن شرب الماء (داء الكلب)، فإنه أول ما يرى الماء يحدث له انقباض في عضلات المريء فلا يستطيع أن يشرب فيخاف من الماء (هيدروفوبيا: خوف من الماء) مع أنه يحتاج إليها جدًّا ويكون في غاية العطش ولا يستطيع أن يشرب؛ ولذا كل شربة ماء وكل نفَس. فدخول هذا النفَس لو كان هذا الهواء فيه دخان أو غازات سامة أو غبار، أو هناك عدد كثير من الناس، فضلًا أن يكون إنسان مريض عنده (كرشة نفس) كما يقولون، سواء في القلب أو في الرئة، فكل حاجة لا بد أن تكون سليمة حتى يتنفس الإنسان: قلب والرئة والشُّعب كلها لا بد أن تكون سليمة، والدم سليم، وامتصاص الأكسجين في الخلايا سليم، والإنزيمات التي تنقل هذا سليمة، وكذلك مراكز المخ سليمة التي تدرك أن الأكسجين موجود؛ فمن ضمن أسباب موت المدمنين للأفيون عدم شعوره بالنقص في الأكسجين، فمراكز المخ حصل لها تخدير فيحدث فشل في مراكز التنفس في المخ مع أن كل الأشياء الأخرى سليمة، ولكن المخ لم يشعر بنقص الأكسجين فيموت الإنسان، فلم يقل له المخ: أسحب نفَسًا، فلا يأخذ نفَسًا وهو لا يدري — شيء تلقائي — مع أنه يحتاج لأن يتنفس، ولكن بسبب مركز التنفس هذا في المخ الذي لا يبلغ المليمتر تحت الميكروسكوب الذي يقيس في الجسم نسبة الأكسجين، فيقول للإنسان: يأخذ نفَسًا، ولو أنه يجري فيقول له تنفس أكثر؛ فسبحان الله، فإن النفَس الواحد فيه من النعم ما لا يحيط الإنسان بها. وكذلك نسبة القلويات والحمضيات في الدم، ونسبة الصوديوم والبوتاسيوم في الدم، فلكي يكون تنفس الإنسان مضبوطًا لا بد أن تكون مضبوطة كما خلقها الله ﷻ، لو حدث بها خلل الإنسان [ينهج] فيحدث له اختلال في الوظيفة التنفسية. فهذا في دخول النفَس وخروجه، كذلك فهي نعم لا تُحصى كثرةً؛ فلو أن الإنسان استشعر نعم الله عليه فلو أنه حمد الله واستشعر أنه عاجز عن حصر ها فتكون بالفعل تملأ ما بين السماوات والأرض. حتى الأشياء البعيدة عن الإنسان نعم عظيمة جدًّا ولكن الناس لم تدركها؛ فالنجوم علامات يُهتدى بها، وفيها مصالح لا يحيط العباد بها علمًا، وكذلك اتزان الأوضاع في الكون، ووجود الأرض حول الشمس ودوران الكواكب في أفلاكها، فهذا الاتزان لو حدث فيه خلل الناس تهلك بلا شك ﴿وَيُمْسِكُ السَّمَاءَ أَنْ تَقَعَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِ﴾. إذا فكر الإنسان في كمال صفات الرب ﷻ يعجز أيضًا، ويدرك مدى عجز الإنسان مع قدرة الله، مدى ذل الإنسان مع عزة الله، مدى ضعة الإنسان مع كبرياء الله، مدى فقر الإنسان مع غنى الرب ﷻ، بل مدى موته في الحقيقة، فهو ميت بالنسبة لحياة الرب ﷻ، وسمع الإنسان محدود للغاية وبصره بالنسبة لسمع وبصر الله ﷻ؛ فيحمد العبد ربه على كماله وعلى نعمه ﷻ، ولا يأخذ العبد ثواب حمده إلا ما استحضره من هذه المعاني في كل مرة وفي كل موضع يحمد الله فيه، ولكن لا شك أن حمده يرضي الله، كما قال النبي ﷺ: «إن الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها، ويشرب الشربة فيحمده عليها» (مسلم). ويأخذ الثواب على قدر حمده لله ﷻ، ولكن كما ورد في الأثر الإسرائيلي: (قال داود: كيف أشكرك وشكرك نعمة تحتاج إلى شكر؟ قال: يا داود، الآن شكرتني)؛ لذا فالعجز عن عد النعم والوقوف على حد كل واحدة منها يجعل العبد يدرك أن الشكر والحمد ليس له حد يستطيع العبد الوصول إليه، ولذلك قال النبي ﷺ: «اللهم لك الحمد كالذي نقول وخيرًا مما نقول» ... «لا أحصي ثناءً عليك أنت كما أثنيت على نفسك». حتى في المضار وحتى في الآلام هذه من النعم؛ فعلى سبيل المثال مراكز إدراك الألم في جسم الإنسان لو أنها فُقدت لتعرض الإنسان لمهالك لا يعرفها، فهو لا يدرك مصادر الخطر فيضع يده في النار أو في الكهرباء ولا يتألم فيهلك ويحترق ولا يتألم، فعدم إدراكه يجعله لا يبتعد عن مصادر هذه الأخطار، فوجود تلك المراكز المدركة للألم مع أنها تجعله يتألم إلا أنها سبب لنجاته وبقائه على قيد الحياة. كذلك الفقر نعمة والغنى نعمة، والمرض نعمة، ولكن لمن يعرف نعمة الله ﷻ؛ فالفقر نعمة [فيجعل الإنسان لا يتكبر ولا يطغى فيدرك عجز نفسه ﴿كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَى * أَنْ رَآهُ اسْتَغْنَى﴾]، والمرض نعمة [فيجعله يعرف قدر الصحة ويجعله يطلب الشفاء من الله]، ولكن لمن يعرف نعمة الله ﷻ؛ فالصبر على المرض والصبر على الفقر والصبر على البلاء له ثواب عظيم جدًّا للإنسان، إذا رضي بقضاء الله ﷻ وصبر على بلائه يعطيه الله أجره بغير حساب؛ فكل هذه نعم قد يدركها العبد الآن وقد يدركها بعد ذلك عند نزولها، وأسعدهم من يراها حينها توجد، فكما قال ﷺ: «عجبًا لأمر المؤمن إن أمره كله خير، وليس ذاك لأحد إلا للمؤمن: إن أصابته سراء شكر فكان خيرًا له، وإن أصابته ضراء صبر فكان خيرًا له» (مسلم).`,
        ] },
      { q: `معنى قوله ﷺ «والصلاة نور» و«الصدقة برهان»`, p: `11–13`,
        n: `أما قوله ﷺ «والصلاة نور» فمعناه أنها تمنع من المعاصي وتنهى عن الفحشاء والمنكر وتهدي إلى الصواب كما أن النور يُستضاء به. وقيل: معناه أنه يكون أجرها نورًا لصاحبها يوم القيامة. وقيل: لأنها سبب لإشراق أنوار المعارف وانشراح القلب ومكاشفات الحقائق لفراغ القلب فيها وإقباله إلى الله تعالى بظاهره وباطنه، وقد قال الله تعالى: ﴿وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ﴾. وقيل: معناه أنها تكون نورًا ظاهرًا على وجهه يوم القيامة، ويكون في الدنيا أيضًا على وجهه البهاء بخلاف من لم يصلِّ. وأما قوله ﷺ «والصدقة برهان» فقال صاحب التحرير: معناه يُفزع إليها كما يُفزع إلى البراهين، كأن العبد إذا سُئل يوم القيامة عن مصرف ماله كانت صدقاته براهين في جواب هذا السؤال. وقال غيره: معناه الصدقة حجة على إيمان فاعلها، فإن المنافق يمتنع منها لكونه لا يعتقدها، فمن تصدق استُدل بصدقته على صدق إيمانه.`,
        o: `هي أقوال في تفسير اللفظ ذكرها النووي كما تقدم، ولم يرجح بينها.`,
        s: `لا تعارض بين هذه الأقوال، فكلها صحيحة؛ فالصلاة نور في قلب المؤمن يبصر به حقائق الخير من الشر ويدرك حقائق الأشياء، لوجود النور في قلبه فيعرف ضرر المعصية فيتركها فيجدها مؤلمة، وهذا من أعظم ما يستعان به على ترك المعاصي، وذلك بالإكثار من الصلاة، فكلما صلى وقع في قلبه نور ﴿وَأَقِمِ الصَّلَاةَ إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَلَذِكْرُ اللَّهِ أَكْبَرُ وَاللَّهُ يَعْلَمُ مَا تَصْنَعُونَ﴾، فالمنكر يجده مؤلمًا فلا يجد نفسه تنازعه إلى فعل المنكر. كثير من الناس يشتكي أنه لا يستطيع الانتهاء من عادة سيئة فنقول له: صلِّ كثيرًا وصُم كثيرًا؛ لأنه كلما صلى وقع في قلبه نور، وكذلك الصبر ضياء، فالصبر يضيء للإنسان، والصلاة والصوم من الصبر، ولذلك يضيء القلب ويشرق بالمعارف. فالقول الأول هو هو القول الثالث، بمعنى أنه يكشف له حقائق الوجود، فهي حقائق موجودة فحقيقة أن الكرة الأرضية هذه صغيرة جدًّا، وأن الكفار من الممكن أن يُهلكوا في لحظة، وأن الأرض يمكن أن تهتز في أي لحظة، وأن البشر ليس لديهم سلطان على شيء منها؛ فكل هذا حق ولكن أكثر الخلق غافلون عن ذلك. فكشف الحقائق إذًا يكون بالإكثار من الصلاة (الصلاة نور)، ولكن أيُّ صلاة؟ صلاة يستحضر فيها ما يتكلم به مما يقرؤه من كتاب الله ومن تسبيحه وحمده وتنزيهه، أما مجرد الحركات الظاهرة فلا تجعل الإنسان يستحضر. وأما أنه يُعطى نورًا حقيقيًّا يوم القيامة فهذا لا شك فيه، فالأدلة تثبت ذلك ﴿يَوْمَ تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ يَسْعَى نُورُهُمْ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ﴾، وأما النور الذي في الوجه في الدنيا فهو حق في حق أهل الإيمان، فيدركون استنارة الوجه وبهاءه في الدنيا، وأن الإنسان يظهر عليه ذلك من قسمات وجهه، ولكن قلة من الناس من يدرك ذلك. ولا شك أن الصلاة من أسباب النور على وجه العبد في الدنيا، كما أنها من أسباب النور يوم القيامة، وفي قبره، وفيها ينكشف الحق ويفرغ القلب فيها لله ﷻ وتمنع من المعاصي، وذكر الله فيها أكبر من نهيها عن الفحشاء والمنكر، ففعل المأمورات أعظم في الجنس من ترك المنهيات، فالاثنان يتحققان في الصلاة، فالإنسان ينشغل بالصلاة عن المحرمات وينشغل بذكر الله الذي هو أكبر. فاللهم اجعلنا مقيمي الصلاة ومن ذريتنا ربنا وتقبل دعائنا. وأما الأقوال في «الصدقة برهان» فهذا كله كلام حسن ولا تعارض بينه، ولا يحتاج إلى ترجيح لأن كلها صحيحة، وهو من اختلاف التنوع، وهو من باب تفسير المعاني، وصحتها جميعًا هو الظاهر.`,
        f: [
          `(ص12) على المعنى الأخير (النور على الوجه في الدنيا): ويمثلون به بالحديث المدرج: عن جابر قال: قال رسول الله ﷺ: «من كثرت صلاته بالليل حسُن وجهه بالنهار» (ابن ماجه 1333) [قال الألباني: ضعيف] [تعليق الأرنؤوط: باطل مرفوعًا، والصواب أنه من كلام شريك، قال محمد بن عبد الله بن نمير — كما في «الكامل» لابن عدي في ترجمة ثابت 2/526 —: باطل، شُبِّه على ثابت، وذلك أن شريكًا كان مزاحًا، وكان ثابت رجلًا صالحًا، فيشبه أن يكون ثابت دخل على شريك، وكان شريك يقول: الأعمش عن أبي سفيان عن جابر عن النبي ﷺ، فالتفت فرأى ثابتًا فقال يمازحه: «من كثرت صلاته بالليل حسن وجهه بالنهار»، فظن ثابت لغفلته أن هذا الكلام الذي قال شريك هو من الإسناد الذي قرأه، فحمله على ذلك، وإنما ذلك قول شريك، والإسناد الذي قرأه متنه معروف. قلنا: وثابت بن موسى كان ضريرًا عابدًا، وهو ضعيف الحديث أيضًا، وأبو سفيان هو طلحة بن نافع. وأخرجه العقيلي في ترجمة ثابت من «الضعفاء» 1/176، وابن حبان في ترجمته من «المجروحين» 1/207، وابن عدي في ترجمته أيضًا من «الكامل» 2/526].`,
          `(ص13–14) على قوله «فمعناه الصبر المحبوب في الشرع، وهو الصبر على طاعة الله تعالى، والصبر عن معصيته، والصبر أيضًا على النائبات وأنواع المكاره في الدنيا»: وهذا هو الصبر المشروع، وهو الصبر مع الله ﷻ، وهو الصبر في الطاعة، وإلا فربما يصبر الإنسان صبرًا على غير الطاعة فيتحمل آلامًا ومشاق، وفي حقيقة الأمر فإن أهل الفساد يصبرون على آلام معاصيهم؛ فالذي يشرب السجائر أليس يصبر على تعب الدخان؟ وكذلك يصبرون على ضرر المخدرات، وتجد الرهبان البوذيين والنصارى يصبروا على الحرمان الفظيع، ولكن كل هذا صبر غير محمود لأنه ليس صبرًا مع الله ﷻ. ولكن الصبر المحمود في الشرع هو الثلاثة: إما (صبر على الطاعة) في بداية الأمر، لأن النفس الإنسانية تميل إلى الكسل والراحة الوهمية، ولذلك فالإنسان يحتاج إلى أن يحبسها على الطاعة ويتحمل بعض المتاعب إلى أن يذوق طعم ولذة الإيمان، عند ذلك فإنه لا يشعر بالتعب أو يزول شعوره بالتعب في ضمن وجود اللذة للإيمان، نسأل الله أن يذيقنا إياها. وكذلك (صبر عن المعصية)، فقبل أن يتعود الإنسان على ترك المعاصي فالنفس ميالة إلى الشهوات لأنها ظلوم جهول، فإذا حدث نوع من التعود على تركها وجد الإنسان مغبتها فابتعد عنها ويقول: سبحان الله كيف يتحملها أهلها! فيزول عنه ألم الحبس عن الشهوة ويجد لذة البعد عنها، مثل الذي لا يشرب السجائر فيشعر كيف يضع إنسان دخانًا في فمه، كيف يدخل السموم من هذا الغباء والجهل العظيم؛ لذلك كل المعاصي من هذا الباب. فالإنسان الذي يغض بصره عن الحرام فإنه مستريح راحة عظيمة، لأن النظرة إلى الحرام تجعل هناك شقاوة في القلب، ربما لا يدري حقيقتها، فربما يعتقد البعض أنه يرتاح عندما يشاهد أفلامًا ومسلسلات ونساء عاريات، ولكنه يحدث له شقاء عجيب، والفاحشة أشد إذا كان لمس أو إذا كان زنى، فكل واحد منهم تصيب الإنسان بكرب الله ﷻ أعلم به، فيعيشون في ضيق عظيم، ولذلك يلجؤون إلى المخرج من شرب المسكر والمخدر وغير ذلك، ويأخذ المزيد فيزداد كربًا أكثر. فالإنسان العاقل المستيقظ المستمتع بالحياة لماذا يريد أن يغيب عن الوعي؟ لماذا يريد أن يعيش في الخيال؟ فالخمرة والمخدرات كلها تغيب العقل الإنساني إدراك ما بين الوهم والخيال والحقيقة، فيتخيل كل الخيالات حقائق، فيجد اللذات من حيث يشتهيها: يريد أن يكون ملكًا فيتخيل أنه ملك، يتخيل أنه يأتي بمئة امرأة فيُنزل ويشعر أنه قد أتى مئة امرأة وهو في غياب المخدرات والخمر، يريد أن يكون سعيدًا فيشعر أنه سعيد، وهذا في الحقيقة خيال ووهم، فيفضل هذه اللذة الوهمية وهي ستأتي له بأضرار بعد ذلك وندم؛ فإنه بمجرد أن يزول أثرها يشعر بأنه نزل من فوق وكأنه يرتطم بالأرض، فيطلع نفسه فوق ثم يرميها تحت، فلا بد وأن يحدث له ألم وندم وتعب وصداع، لأنه اكتشف أنه كان في وهم فيتضايق من حياته، فيرجع للمخدر ثانية فيقول: أحسن شيء أن أغيب عن الوعي، وهو بذلك بالفعل يدمر نفسه. فالإنسان عندما يبتعد عن ذلك ويستغني عنها فيجد أن الصبر عن المعصية فعلًا رحمة بالنفس، فهذه هي البداية ثم يزول هذا الألم الذي هو ألم الحبس عن المعصية، فعلى قدر بُعد الإنسان عن المعاصي على قدر ما يجد الضياء في قلبه (والصبر ضياء). و(الصبر على البلاء وأنواع المكاره) أيضًا من أسباب سعادة الإنسان، فإنه إن استحضر أن هذا قدر الله وأنه ملك لله ﴿إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ﴾ فيرضى بقضاء الله فيكون ذلك خيرًا له، وهو من أعظم أسباب زوال المحنة عن الإنسان، فتتحول حياته إلى حياة سعيدة في الدنيا قبل الآخرة، كما قال شيخ الإسلام ابن تيمية: (ما يصنع أعدائي بي؟ أنا جنتي وبستاني في صدري، إن رحت فهي معي لا تفارقني؛ إن حبسي خلوة، وقتلي شهادة، وإخراجي من بلدي سياحة) الوابل الصيب.`,
          `(ص14) على قول إبراهيم الخواص «الصبر هو الثبات على الكتاب والسنة»: وهذا هو أعلى أنواع الصبر، وهو الصبر على الطاعة، وكما قلنا إن جنس فعل المأمورات أعظم من جنس ترك المنهيات، فالصبر على الطاعة أفضل من الصبر عن المعصية. وعلى قول ابن عطاء «الصبر الوقوف مع البلاء بحسن الأدب»: فهو يتكلم عن نوع من أنواع الصبر، فيتأدب مع الله عند وقوع البلاء دون اعتراض ولا سخط ولا شكوى من الرب إلى الخلق.`,
          `(ص15) على قوله «فأما إظهار البلاء لا على وجه الشكوى فلا ينافي الصبر»: ولذلك قال النبي ﷺ: «بل أنا وارأساه» (البخاري)، و[قالوا: يا رسول الله إنك توعك وعكًا شديدًا، قال: «أجل، إني أوعك كما يوعك رجلان منكم»] (البخاري)؛ فكون الإنسان يقول أنا متعب لا على جهة السخط والشكوى، بل على جهة الخبر أو على جهة الشكوى إلى الله ﴿إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ﴾، فالشكوى إلى الله لها ثواب عظيم ونعمة من الله، فهي عبودية لله سبحانه وتعالى، يبتلي الله المؤمنين ببلايا وتسلط الأعداء وأنواع المحن لكي يشكو العبد إلى الله ﷻ.`,
          `(ص15) على قوله «والقرآن حجة لك أو عليك: أي تنتفع به إن تلوته وعملت به وإلا فهو حجة عليك»: بل كل النعم تكون حجة على العبد إذا لم يشكر ربه عليها ولم يصرفها في طاعة الله؛ فالقرآن يحفظه العبد ثم يتخذه مهنة ولا يعمل به ولا يدعو به ولا يدعو إليه، ولا يحل حلاله ولا يحرم حرامه، ولكن كل همه أنه يتكسب من ورائه أو يدرسه لكي يصلح به دنيا غيره، فيبحث عن الرخص من الرخص ويحرف معاني الآيات وكيف يجعلهم يتركوا الشريعة من غير أن يتهمهم أحد بمخالفة الدين، فيكون القرآن بذلك حجة عليه، فإنه لم ينتفع بالقرآن. وأما إذا آمن به وعمل به ودعا إليه فالقرآن حجة له.`,
          `(ص15) على قوله «كل إنسان يسعى بنفسه فمنهم من يبيعها لله تعالى بطاعته فيعتقها من العذاب، ومنهم من يبيعها للشيطان والهوى باتباعهما فيوبقها»: فمع أول بلوغ الإنسان يبدأ البيع، فكل لحظة ينفقها فهو يبيع شيئًا من عمره: فإما أن يشتري به ما يُرضي به الله سبحانه وتعالى فهذا ينجي نفسه ويعتقها من العذاب ومن سخط الله عز وجل، والإنسان في الدنيا محبوس حبسة تمنعه من الانطلاق للذات الآخرة؛ فإما أن تظل في الحبس، وإما أن تعتق نفسك، فمن حرر نفسه وجعلها في عبودية الله انطلق إلى أنواع المغانم، وأما من باع للشيطان أنفق اللحظات في معصية الله. ولهذا كل إنسان في هذه الحياة يبيع؛ فإن عمره يمر فإما أن يقضيه في طاعة الله، وإما أن ينفقه في معصية الله ويشترى اللذات الفانية واتبع الهوى فيهلك نفسه.`,
        ] },
    ],
  },
  {
    title: `باب وجوب الطهارة للصلاة (ص16–21)`,
    items: [
      { q: `الطهارة شرط في صحة الصلاة: الطهارة من الحدث والطهارة من النجس`, p: `16–17`,
        n: `هذا الحديث («لا تُقبل صلاة بغير طهور») نص في وجوب الطهارة للصلاة، وقد أجمعت الأمة على أن الطهارة شرط في صحة الصلاة.`,
        o: `في الطهارة من النجس خلاف مشهور: فقيل: شرط مطلقًا، وقيل: شرط مع العلم والقدرة (فلا تكون شرطًا مع النسيان أو العجز)، وقيل: واجبة وليست بشرط (يأثم من تركها ولكن تصح صلاته حتى ولو كان عالمًا عامدًا قادرًا على إزالة النجاسة).`,
        s: `المقصود بالطهارة هنا الطهارة من الحدث (الأصغر والأكبر)، وهي المُجمع على أنها شرط مطلقًا سواء (ذاكرًا أو ناسيًا). أما بالنسبة للقدرة والعجز فالذي عليه الجمهور — أو الصحيح الذي دلت عليه الأدلة — أنها شرط مع القدرة [بمعنى أنه لو عجز عن الطهارة انتقل إلى غيرها، ولو عجز عن كل أنواع الطهارة صلى بغيرها (فاقد الطهورين: الماء والتراب)]. أما الطهارة من النجس فهي ليست المقصودة في هذا الحديث ولا في هذا الإجماع المنقول؛ لوجود خلاف مشهور بين كونها شرطًا مطلقًا، أو شرطًا مع العلم والقدرة، أو أنها واجبة وليست بشرط.` },
      { q: `متى فُرضت الطهارة للصلاة؟`, p: `17`,
        n: `قال القاضي عياض: واختلفوا متى فُرضت الطهارة للصلاة؛ فذهب ابن الجهم إلى أن الوضوء في أول الإسلام كان سنة، ثم نزل فرضه في آية التيمم، قال الجمهور: بل كان قبل ذلك فرضًا.`,
        o: `ابن الجهم: كان الوضوء سنة في أول الإسلام ثم نزل فرضه في آية التيمم.`,
        s: `هناك إجماع على أن آية الوضوء نزلت في سورة المائدة، وهي مدنية متأخرة النزول، ولكن يمكن أن يكون ذلك لبيان الأركان في هذه الآية الكريمة (مع أنه كان فرضًا قبل ذلك كما قال الجمهور).` },
      { q: `هل الوضوء فرض على كل قائم إلى الصلاة أم على المُحدِث خاصة؟ (ومعنى آية الوضوء)`, p: `17`,
        n: `قال القاضي: واختلفوا في أن الوضوء فرض على كل قائم إلى الصلاة أم على المحدث خاصة؟ فذهب ذاهبون من السلف إلى أن الوضوء لكل صلاة فرض بدليل قوله تعالى: ﴿إِذَا قُمْتُمْ إِلَى الصَّلَاةِ﴾ الآية. وذهب قوم إلى أن ذلك قد كان ثم نُسخ. وقيل: الأمر به لكل صلاة على الندب. وقيل: بل لم يُشرع إلا لمن أحدث، ولكن تجديده لكل صلاة مستحب، وعلى هذا أجمع أهل الفتوى بعد ذلك ولم يبق بينهم فيه خلاف، ومعنى الآية عندهم: إذا قمتم محدثين.`,
        o: `بعض السلف: الوضوء فرض لكل صلاة ولو لم يُحدث. وقيل: كان ثم نُسخ. وقيل: الأمر به لكل صلاة على الندب.`,
        s: `القول بأن كل من قام إلى الصلاة — سواء كان محدثًا أو غير محدث — فرضٌ عليه أن يتوضأ قولٌ شاذ، وأصبح قولًا مهجورًا، وسيأتي نقل الاتفاق على عدم وجوب الوضوء لكل صلاة. والفرق بين القول الأخير (لم يُشرع إلا لمن أحدث) والذي قبله (الأمر للندب) مبني على تفسير الآية فقط، وإلا فالحكم واحد؛ على أساس أنه سيقدر: (إذا قمتم إلى الصلاة وكنتم محدثين)، أم إذا قمتم إلى الصلاة وتكون على إطلاقها ليس فيها تقدير والأمر في «فاغسلوا» للندب؟ والأقرب هو القول الأخير، وهو أن الآية من أول ما نزلت معناها: إذا قمتم إلى الصلاة وكنتم محدثين؛ لأنها ليست للندب مطلقًا، كلها فيها نوع من التأويل، فأيسرها تأويلًا وأقربها إلى الظاهر تقدير الجمهور؛ لأنه لو قال إن الأمر للندب فهذا تأويل لظاهر القرآن ومخالف لظاهر الأحاديث: «إنها لا تتم صلاة أحدكم حتى يُسبغ الوضوء كما أمره الله ﷻ»، وهذا يفيد الوجوب، فكيف يُحمل هذا على الندب؟ فهذا تأويل بعيد. وأما تقدير (وكنتم محدثين) فيدل عليه السياق، ويدل عليه قوله ﷺ: «لا تُقبل صلاة بغير طهور»، ومن كان متوضئًا فقد حصل الشرط. أما استحباب الوضوء لكل صلاة فنستدل بالسنة عليها من فعله ﷺ، أما الآية ففيمن قام إلى الصلاة وهو محدث.` },
      { q: `ما الموجب للوضوء: الحدث أم القيام إلى الصلاة أم هما معًا؟`, p: `17–18`,
        n: `واختلف أصحابنا في الموجب للوضوء على ثلاثة أوجه: أحدها: أنه يجب بالحدث وجوبًا موسعًا. والثاني: لا يجب إلا عند القيام إلى الصلاة. والثالث: يجب بالأمرين، وهو الراجح عند أصحابنا.`,
        o: `قيل: يجب بالحدث وجوبًا موسعًا. وقيل: لا يجب إلا عند القيام إلى الصلاة.`,
        s: `الخلاف هنا قريب من الخلاف اللفظي، ومسألة أنه يجب بالحدث عند القيام إلى الصلاة هو الذي ذكره هو الثالث (يجب بالأمرين) هو الراجح؛ فإن (الوجوب الموسع) يقتضي أنه لا يجب عليه الوضوء إلا في آخر الوقت، والصحيح أنه يلزمه الوضوء إذا أراد القيام إلى الصلاة وكان محدثًا، وهذا هو معنى (يجب بالأمرين معًا). فلو قلنا يجب بالحدث فقط، أي بمجرد ما يُحدث يجب عليه الوضوء ولكن إلى آخر وقت الصلاة [بقدر ما يسع قدر الصلاة الواجبة في آخر وقتها]، وهذا غير ظاهر؛ لأنه يجب عليه الوضوء إذا أراد أن يصلي أول الوقت، لا يسعه أن يؤخر الوضوء في تلك الحال. وقوله (والثاني: لا يجب إلا عند القيام إلى الصلاة) لا بد من تقدير [إذا كان محدثًا]، فلا بد أنه وجب الوضوء بالحدث، وهو السبب الأول لوجوب الوضوء؛ ولذلك قال في الثالث: (يجب بالأمرين) وهو الراجح، أي عند الحدث وعند القيام إلى الصلاة. والقول الثالث هو الصحيح؛ لأن الثاني لا بد من تقدير فيه، فإنه أهمل (وكان محدثًا)، وإلا فلو قلنا فقط عند القيام إلى الصلاة، فيقول قائل: وماذا عند الحدث؟ فإننا قدرنا (وكنتم محدثين)؛ فالقول الأضبط هو الثالث لأنه جمع القولين السابقين بدون احتياج للتقدير؛ لأن الأصل إذا قلنا أقوالًا فلا ينبغي أن تحوجنا إلى تقديرات، وأن سبب وجوب الوضوء وجود الحدث السابق.` },
      { q: `صلاة الجنازة وسجود التلاوة والشكر بغير طهارة`, p: `18`,
        n: `وأجمعت الأمة على تحريم الصلاة بغير طهارة من ماء أو تراب، ولا فرق بين الصلاة المفروضة والنافلة وسجود التلاوة والشكر وصلاة الجنازة، إلا ما حُكي عن الشعبي ومحمد بن جرير الطبري من قولهما: تجوز صلاة الجنازة بغير طهارة، وهذا مذهب باطل وأجمع العلماء على خلافه.`,
        o: `الشعبي وابن جرير الطبري: تجوز صلاة الجنازة بغير طهارة.`,
        s: `الإجماع صحيح إلا في العاجز عن كليهما (فاقد الطهورين) وتصح صلاته على تلك الحال لعجزه، فإن الله لا يكلف نفسًا إلا وسعها، وإلى هنا انتهى الإجماع (أو التراب)، مع التخصيص الذي قلناه بأن فاقد الطهورين يصلي بغيرهما. نعم فهذا (جواز صلاة الجنازة بغير طهارة) مذهب باطل. وأما سجود التلاوة والشكر ففيه خلاف مشهور، وإذا قصد النووي نقل الإجماع في كل هذا وهو وارد، فلا ينطبق على التلاوة والشكر لأنهم ليسوا صلاة، بل جزء من أجزاء الصلاة، كما أن التسبيح من الصلاة ولا يلزم له الطهارة، وكما أن يقرأ القرآن قائمًا فجائز ولا يلزم له الطهارة، ولو ذكر الله ﷻ جالسًا لما وجبت له الطهارة؛ فكونه على هيئة من هيئات الصلاة يذكر الله ﷻ لا يلزم أن يكون ذلك صلاة. وهذا هو الراجح في مسألة سجود التلاوة والشكر، فلا يجب له الطهارة لعدم وجود دليل يلزم بذلك، ويُنقل عن ابن عمر ﵁ جواز سجود التلاوة بغير طهارة، وهو ترجيح البخاري.` },
      { q: `من صلى مُحدثًا متعمدًا بلا عذر: هل يكفر؟`, p: `18–19`,
        n: `ولو صلى محدثًا متعمدًا بلا عذر أثم ولا يكفر عندنا وعند الجماهير، وحُكي عن أبي حنيفة رحمه الله تعالى أنه يكفر لتلاعبه. ودليلنا أن الكفر للاعتقاد، وهذا المصلي اعتقاده صحيح، وهذا كله إذا لم يكن للمصلي محدثًا عذر.`,
        o: `حُكي عن أبي حنيفة: يكفر لتلاعبه.`,
        s: `لاعتقاده أن صلاته باطلة. والمسألة فيها قول آخر: أنه من صلى بغير وضوء بلا عذر كافر لتركه الصلاة الواجبة عند من يكفر تارك الصلاة، وكما نقله ابن القيم في (الصلاة وحكم تاركها) أن الخلاف في تكفير تارك الصلاة يتفرع منه الخلاف في (تكفير من صلى فاقدًا لأحد شروطها المجمع عليها)، والتكفير للتلاعب وجه قوي فيه احتمال. ولكن قد يكون متعمدًا بغير عذر معتبر، كأن يكون خائفًا من أن يغتسل بسبب ضيق الوقت، أو محرجًا ممن حوله، أو المكان بالنسبة له غير مناسب وغير مهيأ كما ينبغي، وهو لا يخشى على نفسه الهلاك، ولكنه يريد حمامًا نظيفًا جدًّا ويحرج من ترك الصلاة فيصلي مع الناس بغير وضوء؛ فهذا الراجح فيه أنه لا يكفر إذا لم يكن متلاعبًا، فلو كان متلاعبًا بالفعل فهو خارج من الملة. ومن الجهل الفتيا بالتيمم مع وجود الماء بجوارهم من أجل الاشتراك في المظاهرات لكي يصلي صلاة الغائب مع فوات الظهر وربما العصر، فهو لا يخشى فوات وقت ولا شيء من ذلك، فمثل هذا عذر غير مقبول، وصلاتهم باطلة، وكذلك صلاة العيد لا بد لها من الطهارة، ولا يصح التيمم لذلك. وصلاة الجنازة كسائر الصلوات، ما عدا الخلاف المذكور فيها، فالصحيح أنه لا يجزئ التيمم كذلك فيها إلا إذا فقد الماء؛ لقوله تعالى: ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا﴾، فلا بد أن يحصل الصلاة والثواب بالشروط الشرعية.` },
      { q: `حكم صلاة فاقد الطهورين (من لم يجد ماءً ولا ترابًا) وهل يعيد؟`, p: `19–20`,
        n: `أما المعذور كمن لم يجد ماءً ولا ترابًا ففيه أربعة أقوال للشافعي رحمه الله تعالى، وهي مذاهب للعلماء، قال بكل واحد منها قائلون: أصحها عند أصحابنا: يجب عليه أن يصلي على حاله، ويجب أن يعيد إذا تمكن من الطهارة. والثاني: يحرم عليه أن يصلي ويجب القضاء. والثالث: يُستحب أن يصلي ويجب القضاء. والرابع: يجب أن يصلي ولا يجب القضاء، وهذا القول اختيار المزني، وهو أقوى الأقوال دليلًا. فأما وجوب الصلاة فلقوله ﷺ: «وإذا أمرتكم بأمر فأتوا منه ما استطعتم»، وأما الإعادة فإنما تجب بأمر مجدد والأصل عدمه. وكذا يقول المزني: كل صلاة أُمر بفعلها في الوقت على نوع من الخلل لا يجب قضاؤها.`,
        o: `الأصح عند الشافعية: يصلي على حاله ويعيد (فيوجب عليه الصلاة مرتين). وقيل: يحرم أن يصلي ويجب القضاء. وقيل: يُستحب أن يصلي ويجب القضاء.`,
        s: `القول الرابع (يجب أن يصلي ولا يجب القضاء) هو الصحيح بالفعل، ولا تُستحب الإعادة؛ لأنها إذا كانت هذه الصلاة هي الواجبة فالثانية لا تكون نافلة، فكيف ينويها فريضة وتكون نافلة مستحبة؟ فالرأي الأول يوجب عليه الصلاة مرتين [صلاة على الحال، وعندما يتمكن من الطهارة يتوضأ ويصلي]. والثاني (يحرم أن يصلي) لأنه لا يجوز الصلاة مرتين، أما الثاني فيوجب الصلاة مرة واحدة عندما يتمكن من الطهارة لقوله ﷺ: «لا يقبل الله صلاة بغير طهور»، فجعلها على إطلاقها مع القدرة والعجز ومع الذكر والنسيان؛ هناك اتفاق أنها مطلقًا مع الذكر والنسيان، وأما مع القدرة والعجز فالخلاف فيهما باقٍ، فعندما نقول هو شرط مطلقًا مع الذكر والنسيان أي (سواء كان ذاكرًا أو ناسيًا) [كمن نسي أنه انتقض وضوؤه وعرف أنه صلى بغير وضوء ناسيًا فالصلاة باطلة عند جميع الفقهاء ويلزمه أن يعيد]، (فإذا قلنا شرط مع القدرة فإذا عجز عن الطهارة فصلاته باطلة ولا نأمره بالصلاة وعندما يستطيع يصلي وتسقط عنه الصلاة إذا عجز عن الطهارة في الوقت ويلزمه القضاء). وكذلك القول الثالث فيقول إنه يستحب أن يصلي، أتكون هذه هي الفريضة؟ لا تكون الفريضة، ولو نواها فريضة فكيف تكون مستحبة؟ فهذا كلام متناقض. ولذلك الراجح من جهة الدليل أنه يصلي بغير ماء ولا تراب؛ لأن جميع الواجبات تسقط بالعجز والعذر ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾. وقوله «وأما الإعادة فإنما تجب بأمر مجدد»: أي أن القضاء لا يجب إلا بأمر جديد، فأين الأمر الجديد بالإعادة؟ فإذا حان وقت الصلاة وهو عاجز عن الطهارة (الماء والتراب) أمرناه بالصلاة ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾ فليصلِّ إذًا على حاله، وكونه يجب عليه القضاء فأنتم لم تأتوا بدليل، وهذا هو الأصل ولم يرد ما ينقل عنه. وقول المزني: أي أن الشرع هو الذي أذن بفعلها مع وجود الخلل فكيف نأمر بإعادتها؟ ومن أمثلتها: رجل صلى في الوقت جالسًا ثم تمكن من القيام في آخر الوقت لا يؤمر بإعادة الصلاة. ورجل به حدث دائم وصلى أول الوقت (كالمستحاضة ومن به سلس بول) أمرناه بالصلاة رغم خروج الحدث أثناء الصلاة، ومع ذلك صحت صلاته، فإذا زال العذر قبل خروج الوقت صحت الصلاة ولا يؤمر بالإعادة. ورجل اجتهد في إيجاد القبلة فأخطأ فأمرناه بأن يصلي وهو في الأصل مخطئ ولكن لا يعرف، هو لا يعرف وانتهت الصلاة على تلك الحال وعرف خطأه قبل انقضاء الوقت لا إعادة عليه، وبعد انقضاء الوقت بالأولى.` },
      { q: `هل يُفهم من قوله ﷺ «حتى يتوضأ» أن الصلاة لا تُقبل بالتيمم؟`, p: `20`,
        n: `قوله ﷺ في الحديث الثاني: «لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ» معناه حتى يتطهر بماء أو تراب، وإنما اقتصر ﷺ على الوضوء لكونه الأصل والغالب.`,
        o: NO_O,
        s: `لا وجه لمفهوم المخالفة في كلمة (يتوضأ)، فلا يُفهم منها لا تقبل الصلاة بالتيمم؛ لأنه خرج مخرج الغالب {لا وجه لمفهوم المخالفة فيما خرج مخرج الغالب}، فيكون المعنى: لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ (أو ما يقوم مقامه من التيمم)، ومثله الاغتسال إذا كان الحدث حدثًا أكبر.` },
      { q: `الدعاء للولاة الظلمة وأهل المعاصي وامتناع ابن عمر من الدعاء لابن عامر`, p: `20–21`,
        n: `وأما قول ابن عامر: «ادعُ لي» فقال ابن عمر: سمعت رسول الله ﷺ يقول: «لا يقبل الله صلاة بغير طهور ولا صدقة من غلول، وكنت على البصرة»؛ فمعناه أنك لست بسالم من الغلول، فقد كنت واليًا على البصرة وتعلقت بك تبعات من حقوق الله تعالى وحقوق العباد، ولا يُقبل الدعاء لمن هذه صفته، كما لا تُقبل الصلاة والصدقة إلا من متصوِّن. والظاهر — والله أعلم — أن ابن عمر قصد زجر ابن عامر وحثه على التوبة وتحريضه على الإقلاع عن المخالفات، ولم يُرد القطع حقيقة بأن الدعاء للفساق لا ينفع؛ فلم يزل النبي ﷺ والسلف والخلف يدعون للكفار وأصحاب المعاصي بالهداية والتوبة.`,
        o: NO_O,
        s: `«متصوِّن» أي: يصون نفسه عن المعاصي. امتنع ابن عمر ﵁ من الدعاء لوالٍ من ولاة بني أمية (لابن عامر)، وهذا لم يكن على الملأ بل كان بينه وبينه، فما بال هؤلاء الذين يدعون للدعاة على أبواب جهنم على المنابر بزعم أنهم ولاة الأمور! وهذا تلبيس على عباد الله؛ فيمكن أن ندعو لكافر (اللهم اغفر لقومي فإنهم لا يعلمون)، (اللهم أعز الإسلام بأحب الرجلين إليك مثلًا) يدعو لكافر بعينه (اللهم اهدِ فلانًا)، وكذلك يدعو له بالمغفرة والتوبة [فإنه إذا أراد أن يغفر له تاب عليه من الكفر]. ولكن الناس لو دُعي في مقام معين تفهم من الدعاء لهذا الشخص تزكيته والثناء والمحبة والرضا عنه، ولذلك يُشرع ترك الدعاء لمن ظُن منه الظلم فضلًا عن المنافقين والدعاة على أبواب جهنم فضلًا عن الكفرة، والمناسب للمقام التغليظ والزجر. وليس أن الدعاء لولاة الأمور كالبعض يطلق هذا الكلام ويعممه ويجعله قاعدة من قواعد أهل السنة حتى يدعو لأفجر الفجرة وأظلم الظلمة فيدعوا لهم على المنابر ويدعوا لهم بالحفظ والتأييد والتوفيق؛ فهذا يترتب عليه من المفاسد أعظم من مصلحة الدعاء، وكونه يدعو له بينه وبين الله أن يؤيده الله بالحق ويهديه إلى الصراط المستقيم أمر وارد، لكن فعل ابن عمر ﵁ يبين له لماذا يمتنع عن الدعاء له؟ لأنه كان واليًا على البصرة. ولكن الكلام على ما ذكرنا، وهذا فقه عظيم جدًّا نعرف به سبيل الصحابة ﵃، فالبعض ينتسب ويدعي أنه يريد اتباع منهجهم وهو يخالف حقيقة ما كانوا عليه ﵃ من البراءة من الظلم فضلًا عن الكفر والزندقة والنفاق.` },
    ],
  },
  {
    title: `باب صفة الوضوء وكماله (ص22–32)`,
    items: [
      { q: `حكم غسل الكفين في أول الوضوء (ولو لم يقم من النوم)`, p: `23، 32`,
        n: `قوله «فغسل كفيه ثلاث مرات»: هذا دليل على أن غسلهما في أول الوضوء سنة، وهو كذلك باتفاق العلماء. ويُستدل به على استحباب غسل الكفين قبل إدخالهما الإناء وإن لم يكن قد قام من النوم إذا شك في نجاسة يده، وهو مذهبنا، والدلالة منه ظاهرة، وسيأتي بيان هذه المسألة في بابها.`,
        o: NO_O,
        s: `غسل الكفين في أول الوضوء ليس من الواجبات. والصحيح استحباب غسل الكفين وإن لم يكن نائمًا.` },
      { q: `حقيقة المضمضة: هل تُشترط إدارة الماء في الفم ومجُّه؟ (ومثله إمرار اليد في مسح الرأس)`, p: `23`,
        n: `قال أصحابنا: كمالها أن يجعل الماء في فمه ثم يديره فيه ثم يمجه. وأما أقلها فأن يجعل الماء في فيه، ولا يشترط إدارته على المشهور الذي قاله الجمهور. وقال جماعة من أصحابنا: يشترط، وهو مثل الخلاف في مسح الرأس: أنه لو وضع يده المبتلة على رأسه ولم يُمرَّها هل يحصل المسح؟ والأصح الحصول، كما يكفي إيصال الماء إلى باقي الأعضاء من غير دلك. وأما الاستنشاق فهو إيصال الماء إلى داخل الأنف وجذبه بالنفس إلى أقصاه، ويُستحب المبالغة في المضمضة والاستنشاق إلا أن يكون صائمًا فيكره ذلك؛ لحديث لقيط أن النبي ﷺ قال: «وبالغ في الاستنشاق إلا أن تكون صائمًا».`,
        o: `جماعة من الشافعية: تُشترط الإدارة.`,
        s: `(«يديره فيه»: أي يحركه، «ثم يمجه»: أي ثم يلفظه.) والصحيح أنه يحصل المسح بوضع اليد المبتلة ولو لم يُمرَّها؛ فإن الغسل مرور الماء، والمسح إيصال الماء إلى الممسوح.`, },
      { q: `صفة الجمع والفصل في المضمضة والاستنشاق (الأوجه الخمسة)`, p: `24، 32`,
        n: `قال أصحابنا: وعلى أي صفة وصل الماء إلى الفم والأنف حصلت المضمضة والاستنشاق، وفي الأفضل خمسة أوجه: الأول: يتمضمض ويستنشق بثلاث غرفات يتمضمض من كل واحدة ثم يستنشق منها. والثاني: يجمع بينهما بغرفة واحدة يتمضمض منها ثلاثًا ثم يستنشق منها ثلاثًا. والثالث: يجمع أيضًا بغرفة ولكن يتمضمض منها ثم يستنشق ثم يتمضمض منها ثم يستنشق ثم يتمضمض منها ثم يستنشق. والرابع: يفصل بينهما بغرفتين فيتمضمض من إحداهما ثلاثًا ثم يستنشق من الأخرى ثلاثًا. والخامس: يفصل بست غرفات. والصحيح الوجه الأول، وبه جاءت الأحاديث الصحيحة في البخاري ومسلم وغيرهما، وأما حديث الفصل فضعيف، فيتعين المصير إلى الجمع بثلاث غرفات. ويُستدل بحديث عثمان (فمضمض واستنثر) على أن المضمضة والاستنشاق يكونان بغرفة واحدة، ووجه الدلالة أنه ذكر تكرار غسل الكفين والوجه وأطلق أخذ الماء للمضمضة.`,
        o: `بقية الأوجه الأربعة المذكورة.`,
        s: `الوجه الأول (ثلاث غرفات يتمضمض ويستنشق من كل واحدة) هو الصحيح، والأوجه الأخرى ضعيفة جدًّا، والصحيح أن يُقال في هذه المسألة [والصواب] فإن كل الأوجه الأخرى ضعيفة جدًّا. والوجه الثاني من أعسر الأمور ولا يكاد يكفي؛ فإنه سيأخذ ثلاث مرات من نفس الغرفة ويستنشق بالذي تبقى ثلاث مرات، فهذا وجه ضعيف جدًّا، فقد غرَّ القائل قوله ﷺ في صحيح مسلم: «ثم أدخل يده فاستخرجها فمضمض واستنشق من كف واحدة ففعل ذلك ثلاثًا»، فظن أن كل ذلك من غرفة واحدة، والصحيح أنه في كل مرة يتمضمض ويستنشق. والوجه الثالث كله ناتج من أن الفقهاء لم يدرسوا جيدًا روايات الأحاديث، فلو درسوها لوضح الفهم الأول. وأما الاستدلال بحديث عثمان على أنهما بغرفة واحدة فليس فيه دلالة، فهناك أحاديث أخرى توضح العدد.` },
      { q: `تقديم المضمضة على الاستنشاق: استحباب أم اشتراط؟`, p: `24`,
        n: `واتفقوا على أن المضمضة مقدمة على الاستنشاق على كل قول وعلى كل صفة، وهل هو تقديم استحباب أو اشتراط؟ فيه وجهان: أظهرهما اشتراط لاختلاف العضوين. والثاني: استحباب كتقديم يده اليمنى على اليسرى.`,
        o: `أظهر الوجهين عند الشافعية: الاشتراط.`,
        s: `(أو اشتراط) أي اشتراط إذا كانت هي مستحبة عند الجمهور!! اشتراط في تحصيل هذه السنة المؤكدة. والراجح الاستحباب، وأن السنة تحصل لمن خالف في الترتيب، وإذا رتب فهو أفضل. فالوجه الثاني هو الصحيح، فالأظهر استحباب التقديم.` },
      { q: `عدد الغسلات في الوضوء (مرة ومرتين وثلاثًا) واختلاف الرواة في القصة الواحدة`, p: `25`,
        n: `هذا الحديث أصل عظيم في صفة الوضوء، وقد أجمع المسلمون على أن الواجب في غسل الأعضاء مرة مرة، وعلى أن الثلاث سنة، وقد جاءت الأحاديث الصحيحة بالغسل مرة مرة وثلاثًا ثلاثًا وبعض الأعضاء ثلاثًا وبعضها مرتين وبعضها مرة. قال العلماء: فاختلافها دليل على جواز ذلك كله، وأن الثلاث هي الكمال والواحدة تجزئ. وأما اختلاف الرواة فيه عن الصحابي الواحد في القصة الواحدة فذلك محمول على أن بعضهم حفظ وبعضهم نسي، فيؤخذ بما زاد الثقة كما تقرر في قبول زيادة الثقة الضابط.`,
        o: NO_O,
        s: `الحقيقة أنه في مثل هذه الوقائع لا يلزم عدم تكرر القصة؛ فإن تعليم الصحابة للتابعين الوضوء كما فعل النبي ﷺ قد علمهم ذلك مرات، فقد كان يأتي بوضوء ويتوضأ، فلا مانع من أن عثمان ﵁ فعل ذلك عدة مرات، ففي مثل هذا لا مانع فيه من الحمل على التعدد؛ فالتابعي قد يكون رأى هذه الواقعة أكثر من مرة لملازمته للصحابي، فلا مانع من أن يكون قد تكرر الأمر، بخلاف الوقائع الأخرى التي لا يمكن حملها على التعدد، كمسألة الكسوف لأنه معروف أنها لم تحدث إلا مرة واحدة في حياته ﷺ، ولم يكن للنبي ﷺ مثلًا إبراهيمان [يوم أن مات إبراهيم]، فالحمل على التعدد غير ظاهر إلا إذا كان هناك خسوف قمر لا نعرفه.` },
      { q: `تكرار مسح الرأس ثلاثًا`, p: `25–26`,
        n: `واختلف العلماء في مسح الرأس: فذهب الشافعي في طائفة إلى أنه يستحب فيه المسح ثلاث مرات كما في باقي الأعضاء. وذهب أبو حنيفة ومالك وأحمد والأكثرون إلى أن السنة مرة واحدة ولا يُزاد عليها. والأحاديث الصحيحة فيها المسح مرة واحدة، وفي بعضها الاقتصار على قوله «مسح». واحتج الشافعي بحديث عثمان الآتي في صحيح مسلم «أن النبي ﷺ توضأ ثلاثًا ثلاثًا»، وبما رواه أبو داود في سننه «أنه ﷺ مسح رأسه ثلاثًا»، وبالقياس على باقي الأعضاء، وأجاب عن أحاديث المسح مرة واحدة بأن ذلك لبيان الجواز، وواظب ﷺ على الأفضل.`,
        o: `الشافعي وطائفة: يستحب مسح الرأس ثلاثًا.`,
        s: `ما هو الدليل؟ هذه المواظبة أقصى شيء أنه فعلها — مسح رأسه ثلاثًا — مرة، والمحققون من العلماء يقولون: رغم أن سند أبي داود صحيح لكن الظاهر أنه روي بنفس مخرج الحديث وهناك الروايات المصرحة بأنها (مرة واحدة)، والظاهر أنه شذوذ، وأن راويًا روى حديث عثمان بالمعنى (ثلاثًا ثلاثًا) فلما جاء عند الرأس قال: فمسح رأسه (ثلاثًا)، فتكون رواية ثلاثًا في سنن أبي داود شاذة، وهذا ما عليه أئمة علماء الحديث الكبار كالبخاري ومسلم. والصحيح ما ذكره ابن القيم في زاد المعاد قال: (الصحيح (رواية مسلم توضأ ثلاثًا ثلاثًا) غير صريح، والصريح غير صحيح)، وهذا نصه: [وكان يمسح رأسه كله، وتارة يقبل بيديه ويدبر، وعليه يُحمل حديث من قال: مسح برأسه مرتين، والصحيح أنه لم يكرر مسح رأسه، بل كان إذا كرر غسل الأعضاء أفرد مسح الرأس، هكذا جاء عنه صريحًا، ولم يصح عنه ﷺ خلافه البتة، بل ما عدا هذا: إما صحيح غير صريح: كقول الصحابي: توضأ ثلاثًا ثلاثًا، وكقوله: مسح برأسه مرتين؛ وإما صريح غير صحيح: كحديث ابن البيلماني عن أبيه عن عمر أن النبي ﷺ قال: «من توضأ فغسل كفيه ثلاثًا» ثم قال: «ومسح برأسه ثلاثًا»، وهذا لا يُحتج به، وابن البيلماني وأبوه مضعفان، وإن كان الأب أحسن حالًا. وكحديث عثمان الذي رواه أبو داود أنه ﷺ مسح رأسه ثلاثًا. وقال أبو داود: أحاديث عثمان الصحاح كلها تدل على أن مسح الرأس مرة، ولم يصح عنه في حديث واحد أنه اقتصر على مسح بعض رأسه البتة، ولكن كان إذا مسح بناصيته كمَّل على العمامة]. ويمكن أن يقال: كلام الشيخ الألباني بعد تصحيحه للأحاديث رغم أنها شاذة عند جمهور المحدثين (ومسح برأسه ثلاثًا)، فهذا التصريح عند الجمهور قالوا: يفعل أحيانًا.` },
      { q: `الواجب في الرجلين: الغسل أم المسح؟`, p: `26`,
        n: `وأجمع العلماء على وجوب غسل الوجه واليدين والرجلين واستيعاب جميعهما بالغسل، وانفردت الرافضة عن العلماء فقالوا: الواجب في الرجلين المسح، وهذا خطأ منهم، فقد تظاهرت النصوص بإيجاب غسلهما، وكذلك اتفق كل من نقل وضوء رسول الله ﷺ على أنه غسلهما.`,
        o: `الرافضة: الواجب في الرجلين المسح.`,
        s: `بل هناك بعض من علماء أهل السنة خالفوا في إيجاب غسل الرجلين، وليس فقط الرافضة [كابن جرير]؛ فمن أهل السنة من يوجب الغسل أو المسح مع الاستيعاب، وهذا قول طائفة من أهل السنة، ولكن المشهور أنه قول الرافضة. والصحيح وجوب الغسل، وأن المسح إذا كان فيهما خفان.` },
      { q: `قدر الواجب في مسح الرأس`, p: `26–27`,
        n: `وأجمعوا على وجوب مسح الرأس، واختلفوا في قدر الواجب فيه: فذهب الشافعي في جماعة إلى أن الواجب ما يُطلق عليه الاسم ولو شعرة واحدة، وذهب مالك وأحمد وجماعة إلى وجوب استيعابه، وقال أبو حنيفة — رحمه الله تعالى — في رواية: الواجب ربعه.`,
        o: `الشافعي: ما يُطلق عليه اسم المسح ولو شعرة واحدة. وأبو حنيفة في رواية: الربع.`,
        s: `(ما يُطلق عليه الاسم) أي اسم المسح. ومسألة التحديد (بالربع) من أضعف الأقوال؛ لأنه لا بد فيه من نص. والراجح قول الشافعي، والأحوط قول أحمد ومالك وهو السنة؛ أعني أن هذا الفعل هو السنة، فإن القول بالوجوب يحتاج إلى دليل، فإن الآية أطلقت المسح، والآية بيِّنة وليست مجملة تحتاج إلى بيان وكونها بيَّنه، فما أُطلق عليه مسحٌ فهو مسح، ويطلق على مسح أدنى جزء من الرأس.` },
      { q: `حكم المضمضة والاستنشاق في الوضوء والغسل`, p: `27–28`,
        n: `واختلفوا في وجوب المضمضة والاستنشاق على أربعة مذاهب: أحدها: مذهب مالك والشافعي وأصحابهما أنهما سنتان في الوضوء والغسل، وذهب إليه من السلف الحسن البصري والزهري والحكم وقتادة وربيعة ويحيى بن سعيد الأنصاري والأوزاعي والليث بن سعد، وهو رواية عن عطاء وأحمد. والمذهب الثاني: أنهما واجبتان في الوضوء والغسل لا يصحان إلا بهما، وهو المشهور عن أحمد بن حنبل، وهو مذهب ابن أبي ليلى وحماد وإسحاق بن راهويه، ورواية عن عطاء. والمذهب الثالث: أنهما واجبتان في الغسل دون الوضوء، وهو مذهب أبي حنيفة وأصحابه وسفيان الثوري. والمذهب الرابع: أن الاستنشاق واجب في الوضوء والغسل والمضمضة سنة فيهما، وهو مذهب أبي ثور وأبي عبيدة وداود الظاهري وأبي بكر بن المنذر ورواية عن أحمد.`,
        o: `المشهور عن أحمد: واجبتان في الوضوء والغسل. أبو حنيفة: واجبتان في الغسل دون الوضوء. أبو ثور وداود وابن المنذر: الاستنشاق واجب والمضمضة سنة.`,
        s: `سبب الخلاف: هل الآية فيها إجمال أم لا؟ وهل يصح الزيادة عليها من الأوامر الواردة من النبي ﷺ أم لا؟ فمن قال إن الآية مجملة يقول: (غسل الوجه واجب) والوجه مجمل بيَّنه النبي ﷺ بفعله، فبيَّن أن باطنه الأنف والفم. ومن قال إن الآية بيِّنة لا يقبل هذا الاستدلال، يقول: الوجه معلوم في اللغة ولدى المخاطبين من العرب، بدليل أن كل من وصف وضوء النبي ﷺ قال: غسل وجهه ثلاث مرات، وفرَّق بين هذا وبين (مضمض واستنشق)، وقالوا: والوجه ما يواجه به، والنبي ﷺ في مقام التعليم للأعرابي المسيء في صلاته قال: «إنها لا تتم صلاة أحدكم حتى يُسبغ الوضوء كما أمره الله ﷻ، فيغسل وجهه ويديه إلى المرفقين ويمسح برأسه ورجليه إلى الكعبين...» (سنن أبي داود)، فذكر صفة الوضوء ولم يزد على ألفاظ الآية، وتأخير البيان عن وقت الحاجة لا يجوز، وهذا في مقام التعليم لجاهل، فلو كانت المضمضة والاستنشاق واجبتين لبيَّنه النبي ﷺ. وهذا من أقوى الصوارف للأمر الوارد من الوجوب للاستحباب، وهو يجيب عن الاستدلال الثاني؛ فهم اختلفوا بسبب أن الآية مجملة أم بيِّنة، والوجه الثاني أن هناك أوامر من النبي ﷺ، وهذا هو نفس السبب في الفرق بين المذهب الثالث والرابع؛ لأن البعض لم يبلغه الأمر بالمضمضة، فالأمر بالاستنشاق والاستنثار وارد في الصحيح، والأمر بالمضمضة وارد في السنن فقط («إذا توضأت فمضمض» سنن أبي داود)، فالكثير لم يبلغه الحديث فقالوا بوجوب الاستنشاق لأن الأمر به هو الوارد في الصحيح والأمر للوجوب، ولكن يلزمه القول بوجوب المضمضة لوجود الأمر فيها (إذا توضأت فمضمض)، وحديث المسيء من أقوى الصوارف للأمر الوارد من الوجوب إلى الاستحباب، فهو لم يزد على ذلك، ونقول: إن باطن الوجه ليس بوجه، فالوجه هو ما يواجه به. وشيء ثالث يحتج به من أوجب قالوا: المواظبة والتكرار من النبي ﷺ، وهو دليل على الوجوب، وهذا الأصل فيه منازعة (فليس كل ما واظب عليه النبي ﷺ وكرره وداوم عليه يكون واجبًا، بل يمكن أن يكون مستحبًّا كالوتر وركعتي الفجر، والفعل نفسه لا يدل على الوجوب بنفسه ما لم يكن بيانًا لمجمل واجب). فأصح الأقوال قول جمهور أهل العلم، وهو مذهب مالك والشافعي ورواية عن أحمد: أن المضمضة والاستنشاق من السنن المؤكدة في الوضوء والغسل، والآية بيِّنة، وهي سنة مؤكدة لعدم الذكر في الآية والحديث، وهو من رواية أبي داود وابن حبان، وهي رواية صحيحة فيها الاقتصار على تلاوة ما في الآية ولم يزد عليها، فهذا الكلام بيِّن في مقام البيان، وبالتالي لا يجوز أن يؤخر بعد ذلك واجب. وأما سبب الخلاف بين المذهب الأول والثاني (قالوا الغسل ورد عامًّا فيغسل كل البدن) نقول: نعم، ولكن الظاهر منه وليس الباطن، ومسألة أن الفم له حكم الظاهر في الصيام لا يلزم منه أن يكون له حكم الظاهر في الوضوء والغسل؛ والغسل هو تعميم البدن بالماء، وهو قد عمَّ البدن بالماء، كما لا يجب غسل باطن العينين مع كونهما يواجه بهما في كثير من الأمور، لكن العينين باطن لوجود الجفنين فوقهم، فإذا غسل الأجفان فقد صح ذلك الوضوء والغسل؛ فالراجح أنه سنة فيهما.` },
      { q: `هل يُشترط الدلك في الوضوء والغسل؟`, p: `28`,
        n: `واتفق الجمهور على أنه يكفي في غسل الأعضاء في الوضوء والغسل جريان الماء على الأعضاء، ولا يشترط الدلك، وانفرد مالك والمزني باشتراطه.`,
        o: `مالك والمزني: يُشترط الدلك.`,
        s: `سبب اختلافهم الاختلاف في مسمى الغسل: هل الغسل بمعنى الدلك؟ الراجح لا؛ لأنه قال: «وأفاض على جسده» في الغسل، وهناك أجزاء من البدن ربما يصعب على الكثير الوصول إليها بالدلك كأجزاء من الظهر، ولو كان ذلك واجبًا لأكد عليه الشرع. وكما قلنا أن الغسل هو جريان الماء.` },
      { q: `وجوب غسل المرفقين والكعبين، والمراد بالكعبين`, p: `28–29`,
        n: `واتفق الجماهير على وجوب غسل الكعبين والمرفقين، وانفرد زفر وداود الظاهري بقولهما: لا يجب. واتفق العلماء على أن المراد بالكعبين العظمان الناتئان بين الساق والقدم، وفي كل رجل كعبان، وشذت الرافضة فقالت: في كل رجل كعب، وهو العظم الذي في ظهر القدم، وحُكي هذا عن محمد بن الحسن ولا يصح عنه. وحجة العلماء في ذلك نقل أهل اللغة والاشتقاق، وهذا الحديث الصحيح الذي نحن فيه، وهو قوله «فغسل رجله اليمنى إلى الكعبين ورجله اليسرى كذلك»، فأثبت في كل رجل كعبين.`,
        o: `زفر وداود الظاهري: لا يجب غسل المرفقين والكعبين. والرافضة: الكعب العظم الذي في ظهر القدم.`,
        s: `الصحيح وجوب الغسل؛ لأنه [إلى المرفقين] فعندما تكون الغاية جزءًا من التي قبلها فتدخل في الحد، أما إذا كانت الغاية منفصلة عما قبلها فيكون فيها الإجمال المحتمل، والسنة قد أكدت هذا، ففي صحيح مسلم عن نعيم بن عبد الله المجمر قال: «رأيت أبا هريرة يتوضأ فغسل وجهه فأسبغ الوضوء، ثم غسل يده اليمنى حتى أشرع في العضد، ثم يده اليسرى حتى أشرع في العضد، ثم مسح رأسه، ثم غسل رجله اليمنى حتى أشرع في الساق، ثم غسل رجله اليسرى حتى أشرع في الساق، ثم قال: هكذا رأيت رسول الله ﷺ يتوضأ». وأما الرافضة فيقصدون بظهر القدم الجزء الأعلى منها، فستجد أمام الأصبع الأكبر في العظمة التي وراء الأصبع، فإن الصابع الكبير فيه من الأمام عقلتين ثم عظمة طويلة وفي آخرها عظمة بارزة، فيقولون هذه هي الكعب، وهذا كلام باطل. (وقوله «فغسل يده اليمنى إلى المرفق» [ثم غسل يده اليمنى إلى المرفق] لأن المرفق واحد، فلا يوجد مرفقين).` },
      { q: `من خُلق له عضو زائد أو قُطع بعض أعضاء وضوئه`, p: `29`,
        n: `وقال أصحابنا: ولو خُلق للإنسان وجهان وجب غسلهما، ولو خُلق له ثلاثة أيدٍ أو أرجل أو أكثر وهي متساويات وجب غسل الجميع. وإن كانت اليد الزائدة ناقصة وهي نابتة في محل الفرض وجب غسلها مع الأصلية، وإن كانت نابتة فوق المرفق ولم تحاذِ محل الفرض لم يجب غسلها، وإن حاذته وجب غسل المحاذي خاصة على المذهب الصحيح المختار، وقال بعض أصحابنا: لا يجب. ولو قُطعت يده من فوق المرفق فلا فرض عليه فيها، ويستحب أن يغسل بعض ما بقي لئلا يخلو العضو من طهارة، فلو قُطع بعض الذراع وجب غسل باقيه.`,
        o: NO_O,
        s: `وهذه المسائل هي التي وسعت كتب المتأخرين بلا فائدة وجعلت الفقه يتعسر على أصحابه، وهي بالتأكيد واردة أن تحدث في اليدين والرجلين وفي الوجه كذلك، ولكنه يموت غالبًا؛ فهي في بعض هذه المسائل لم يوجد ولا يمكن أن يوجد، وفي بعضها نادر الحدوث واحد في كل العشرة مليون مثلًا. ومن قُطعت ساقه أو قدمه سقط عنه الفرض؛ فلو قُطعت يده من الرسغ فيجب غسل الباقي، ولو لبس رجل رجلًا صناعية فهل يغسل الرجل الصناعية في الوضوء؟ لا، فقد سقط عنه الفرض، ومن قُطع له أصبع فيجب غسل الباقي، فإذا تجاوز إلى أن قُطع من الساق سقط عنه الفرض.` },
      { q: `هل تُكفِّر الطهارة والصلاة الكبائر؟ (قوله ﷺ «غُفر له ما تقدم من ذنبه»)`, p: `30`,
        n: `إنما قال ﷺ «نحو وضوئي» ولم يقل «مثل»؛ لأن حقيقة مماثلته ﷺ لا يقدر عليها غيره، والمراد بالغفران الصغائر دون الكبائر.`,
        o: NO_O,
        s: `الحديث في مسلم عن أبي هريرة أن رسول الله ﷺ كان يقول: «الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفرات ما بينهن إذا اجتنب الكبائر»، والصلوات الخمس داخل فيها الوضوء بلا شك، فيُحمل المطلق على المقيد (فالمراد الصغائر).` },
      { q: `ركعتا الوضوء (سنة الوضوء): حكمهما، وفعلهما في أوقات النهي، وحصولهما بالفريضة`, p: `30`,
        n: `وفيه استحباب صلاة ركعتين فأكثر عقب كل وضوء وهو سنة مؤكدة. قال جماعة من أصحابنا: ويفعل هذه الصلاة في أوقات النهي وغيرها لأن لها سببًا، واستدلوا بحديث بلال ﵁ المخرج في صحيح البخاري أنه كان متى توضأ صلى وقال: إنه أرجى عمل له. ولو صلى فريضة أو نافلة مقصودة حصلت له هذه الفضيلة كما تحصل تحية المسجد بذلك.`,
        o: NO_O,
        s: `فعلهما في أوقات النهي لأن لهما سببًا هو الصحيح. ومعنى حصول الفضيلة بالفريضة: أنه لو صلى فريضة وقد نوى أنه يصلي عقب الوضوء ركعتين، وحتى لو كانوا ثلاث ركعات فقد قلنا ركعتين أو أكثر؛ لأنه لو صلى ثلاثًا فقد صلى ركعتين، وكذلك إذا صلى نافلة وقصد اتباع السنة في صلاة ركعتين عقب الوضوء (سنة الوضوء)، بمعنى أنه نوى ألا يجلس حتى يصلي ركعتين امتثالًا لأمر النبي ﷺ فيصح منه وأُثيب وحصلت له الفضيلة. فتداخل النيات بين [النوافل المطلقة وأخرى مقيدة، أو بين الفرض ونفل مطلق (صلى ركعتين)] بهذه الطريقة مشروع.` },
      { q: `معنى «لا يحدِّث فيهما نفسه» وحصول الفضيلة مع الخواطر`, p: `30–31`,
        n: `المراد لا يحدث بشيء من أمور الدنيا وما لا يتعلق بالصلاة، ولو عرض له حديث فأعرض عنه بمجرد عروضه عُفي عن ذلك وحصلت له هذه الفضيلة إن شاء الله تعالى؛ لأن هذا ليس من فعله، وقد عُفي لهذه الأمة عن الخواطر التي تعرض ولا تستقر. قال القاضي عياض: وقال بعضهم: هذا الذي يكون بغير قصد يُرجى أن تُقبل معه الصلاة ويكون دون صلاة من لم يحدث نفسه بشيء؛ لأن النبي ﷺ إنما ضمن الغفران لمراعي ذلك لأنه قلَّ من تسلم صلاته من حديث النفس، وإنما حصلت له هذه المرتبة لمجاهدة نفسه من خطرات الشيطان ونفيها عنه ومحافظته عليها حتى لم يشتغل عنها طرفة عين وسلم من الشيطان باجتهاده وتفريغه قلبه. هذا كلام القاضي، والصواب ما قدمته.`,
        o: `القاضي عياض عن بعضهم: من عرض له حديث بغير قصد تُرجى قبول صلاته لكنها دون صلاة من لم يحدث نفسه بشيء.`,
        s: `كلام القاضي بأن صلاته تكون دون من لم يحدث نفسه بشيء كلام صحيح، ولكن نرجو حصول الفضيلة لمن جاهد نفسه في الاستحضار في الصلاة.` },
      { q: `الزيادة على الثلاث في الوضوء، والشك في العدد، والزيادة على المرفقين والكعبين (إطالة الغرة)`, p: `31–32`,
        n: `وقد أجمع العلماء على كراهة الزيادة على الثلاث، والمراد بالثلاث المستوعبة للعضو، وأما إذا لم تستوعب العضو إلا بغرفتين فهي غسلة واحدة. ولو شك هل غسل ثلاثًا أم اثنتين؟ جعل ذلك اثنتين وأتى بثالثة، هذا هو الصواب الذي قاله الجماهير من أصحابنا. وقال الشيخ أبو محمد الجويني من أصحابنا: يجعل ذلك ثلاثًا ولا يزيد عليها مخافة من ارتكاب بدعة بالرابعة، والأول هو الجاري على القواعد، وإنما تكون الرابعة بدعة ومكروهة إذا تعمد كونها رابعة. وقد يُستدل بقول ابن شهاب هذا من يكره غسل ما فوق المرفقين والكعبين، وليس ذلك بمكروه عندنا بل هو سنة محبوبة، وسيأتي بيانها في بابها إن شاء الله تعالى، ولا دلالة في قول ابن شهاب على كراهته؛ فإن مراده العدد كما قدمناه، ولو صرح ابن شهاب أو غيره بكراهة ذلك كانت سنة النبي ﷺ الصحيحة مقدمة عليه.`,
        o: `أبو محمد الجويني: من شك يجعلها ثلاثًا ولا يزيد مخافة البدعة. وبعضهم استدل بقول ابن شهاب على كراهة غسل ما فوق المرفقين والكعبين.`,
        s: `بل الظاهر تحريمه (الزيادة على الثلاث)؛ لأن النبي ﷺ قال: (ثم قال: «هكذا الوضوء، فمن زاد على هذا أو نقص فقد أساء وظلم» — أو «ظلم وأساء» —) (د 135) [قال الألباني: حسن صحيح دون قوله «أو نقص» فإنه شاذ]، فهي عند الجميع: (ثم قال: «هكذا الوضوء، فمن زاد على هذا فقد أساء وتعدى وظلم»)، وقد يقصد بالنقص النقص عن المرة الواحدة أو عن جزء من الأجزاء فلا يتم غسل العضو كاملًا. أما الزيادة فتشمل الزيادة في العدد أو التعبد بغسل ما زاد على ذلك كمسح الرقبة. أما لو أنه غسلها لأن بها ترابًا، أو غسل رأسه بعد الوضوء لحرارة الجو، فلا يضره ذلك. والكراهة هنا كراهة شرعية تشمل المحرم والمكروه. وفي الشك: فإذا كان هناك وسوسة يبني على الظن الراجح. وأما الزيادة على المرفقين والكعبين: فالراجح أن الجزء المستحب غسله هي الشروع في العضد والشروع في الساق، أما أن يصل إلى الإبطين فهذا قول أبي هريرة وهو مرجوح. وهي (رواية مسلم): [ثم يده اليسرى حتى أشرع في العضد، ثم مسح رأسه، ثم غسل رجله اليمنى حتى أشرع في الساق] صحيح مسلم.` },
    ],
  },
  {
    title: `باب فضل الوضوء والصلاة عقبه (ص32–45)`,
    items: [
      { q: `الوضوء في فناء المسجد وداخل المسجد`, p: `34–35`,
        n: `قوله (وهو بفناء المسجد) هو بكسر الفاء وبالمد، أي بين يدي المسجد وفي جواره.`,
        o: NO_O,
        s: `الفناء هو المكان المتسع الذي بجوار المسجد، وقد يُفهم الفناء على أنه جزء منه، ولكن ظاهر الكلام أنه خارج المسجد. الوضوء الأصل فيه أنه يتوضأ خارج المسجد إلا إذا كان لا يضر، فإذا خُصص مكان داخل المسجد فلا بأس أن يتوضأ داخل المسجد إذا لم يكن يتأذى أحد من الماء. وللعلم فإن دورات المياه الحديثة كلها هي خارج المسجد حتى ولو كانت ضمن بناء المسجد، إلا أنها حكمًا خارج المسجد طالما هناك باب يفصل بينها وبين مكان الصلاة فهي خارج المسجد، وقد تجد بعض المساجد بها حوض داخل المسجد بجوار مكان الصلاة، ولكن الأصل أن الوضوء يكون خارج المسجد. والغسل كذلك، ولكن الغسل فيه أمر الستر زيادة على الوضوء. فالغرض أن الفناء ليس معناها أنه داخل المسجد بل هو بجوار المسجد، فلا يظن أحد أنه توضأ داخله بل توضأ خارج المسجد.` },
      { q: `الحلف من غير استحلاف، وكثرة الحلف`, p: `35`,
        n: `قوله (والله لأحدثنكم حديثًا) فيه جواز الحلف من غير ضرورة الاستحلاف.`,
        o: `بعض العلماء: يكره كثرة الحلف لورود النهي عن ذلك كتابًا وسنة.`,
        s: `يكرر النووي الاستدلال على هذه المسألة كثيرًا؛ لأجل أن بعض العلماء قالوا بكراهة كثرة الحلف لورود النهي عن ذلك كتابًا وسنة، فقد يظن البعض أن الحلف مكروه إلا أن يستحلف عند القاضي، والحديث يدل على المشروعية؛ فيستحب أن يؤكد به الكلام في الأمور الشرعية لتكون أوثق في نفوس السامعين وأوضح عندهم وأدعى إلى حفظها، وقد حلف النبي ﷺ مرات من غير استحلاف، وحلف الصحابة ﵃. وأما المكروه فالحلف في أمور البيع والأمور التافهة التي لا فائدة من تأكيدها، وكثرة الحلف فيها تجريء الإنسان فيحلف على مجرد الظن ثم يحلف على الاحتيال ثم يحلف على الكذب، وكثرة الحلف أمر ضار، وقد كان السلف يضربون الصغار على الأيمان والعهود حتى يمنعونهم من ذلك؛ فوجه الجمع كما ذكرنا يحمل كل حديث على ما يناسبه، فالحلف في الأمور المشروعة الدينية والتي هي من باب بلاغ الحق ونحو ذلك والاستحلاف عند القاضي، وعند من له أن يحلفه أو عند من يقوم مقامه فهو أكد بل هو واجب إذا توجه إليه اليمين، والنهي يكون عن الأمور التافهة أو على مجرد الاحتمال والذي يترتب عليها بعد ذلك الحلف على الظن ثم الكذب.` },
      { q: `لزوم التحديث وتبليغ العلم، ومعنى قول عثمان «لولا آية في كتاب الله ما حدثتكم»`, p: `35–36`,
        n: `معناه: لولا أن الله تعالى أوجب على من علم علمًا إبلاغه لما كنت حريصًا على تحديثكم ولست متكثرًا بتحديثكم. ... واختلف العلماء في تأويل ذلك: ففي مسلم قول عروة: إن الآية هي قوله تعالى: ﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ﴾ وعلى هذا لا تصح رواية النون. وفي الموطأ قال مالك: أُراه يريد هذه الآية: ﴿وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ﴾ الآية، وعلى هذا تصح الروايتان، ويكون معنى رواية النون: لولا أن معنى ما أحدثكم به في كتاب الله تعالى ما حدثتكم به لئلا تتكلوا. قال القاضي: والآية التي رآها عروة وإن كانت نزلت في أهل الكتاب ففيها تنبيه وتحذير لمن فعل فعلهم وسلك سبيلهم، مع أن النبي ﷺ قد عمم في الحديث المشهور «من كتم علمًا ألجمه الله بلجام من نار». هذا كلام القاضي، والصحيح تأويل عروة.`,
        o: `مالك: أراد آية ﴿وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ﴾ (وعليه تصح رواية «لولا أنه»).`,
        s: `هذا يدل على أنه أخلص لله ﷻ في أمر التحديث، فلولا الآية لما حدثهم فلا يريد تكثرًا بهم أو شهرة للحديث، وكذلك كان كبار الصحابة ﵃؛ فتجد كبار الصحابة والمبشرين بالجنة ليس لهم من الحديث ما لغيرهم، فهل هذا كما ذكرنا لم يكن رغبة في التكثر في إسماع الناس الحديث، وكانوا لا يحرصون على صحبة الناس كثيرًا إلا في الخير، فكانوا يكتفون بتحديث غيرهم ممن في زمانهم من الصحابة ﵃ وهم مشغولون بأنواع الطاعات الأخرى. وهذا يدل على لزوم التحديث وإبلاغ العلم إذا لم يقم به من تقوم به الكفاية، وكذلك فيشرع التحديث إذا كانت المصلحة راجحة في تعليم الناس، والظاهر تعدد الوقائع التي توضأ فيها عثمان أمام الناس، وهذا دليل على لزوم إبلاغ العلم. والآية وإن نزلت في بني إسرائيل إلا أن العبرة بعموم اللفظ لا بخصوص السبب، فالصحابة ﵃ كانوا يعملون بالآيات التي نزلت في أهل الكتاب خصوصًا بعد قوله: ﴿مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ﴾ صريح في أن هذا في بني إسرائيل، ومع ذلك فهم يحتجون بعموم الآية في لزوم الإبلاغ، ويعتبر عثمان أنه لو لم يبلغ غيره صفة الوضوء وفضل الوضوء والصلاة عقبه أن ذلك ربما دخل في كتمان العلم ورأى لزومًا عليه أن يبلغ هذا العلم ﵁. وتأويل عروة هو الظاهر والله أعلم، ولولا لفظ (آية) هي الرواية الأشهر والأصح عند أكثر الرواة فهي مرجحة على (أنه لولا أنه في كتاب الله)، وسياق الكلام يقتضي أنه إنما حدثه من أجل إقامة الدين وتعليم العلم، وليس لمجرد الذكر أو الفضل أو خوفًا من أن يتكلوا.` },
      { q: `الوضوء على وجه يصح عند جميع العلماء (الخروج من الخلاف)، ومتى يُشرع؟`, p: `36–41`,
        n: `وفي هذا الحديث الحث على الاعتناء بتعلم آداب الوضوء وشروطه والعمل بذلك والاحتياط فيه والحرص على أن يتوضأ على وجه يصح عند جميع العلماء ولا يترخص بالاختلاف، فينبغي أن يحرص على التسمية والنية والمضمضة والاستنشاق والاستنثار واستيعاب مسح الرأس ومسح الأذنين ودلك الأعضاء والتتابع في الوضوء وترتيبه وغير ذلك من المختلف فيه، وتحصيل ماء طهور بالإجماع.`,
        o: NO_O,
        s: `قوله (يُحسن الوضوء) تشمل الوضوء الحسن الذي لا نزاع فيه، وهو الذي على السنة؛ فإن من توضأ على السنة فقد أجزأته عند جميع العلماء، أما مواضع الاختلاف فقد يكون هذا الوضوء ليس بحسن عند طائفة، فالاحتياط ألا يترخص بالاختلاف. والإمام النووي بلا شك لم يقصد الترخص بالاختلاف، بل يقصد أنه حتى لو الراجح عنده مثلًا [عدم وجوب التسمية] فينبغي ألا يأخذ بالرخصة في ذلك على مذهبه بل يحرص على التسمية، ولا يقل [المسألة فيها خلاف] فيترك الأمر ويرد على مخالفه بأن المسألة فيها خلاف طالما يسعه الخروج من الخلاف؛ وذلك لأن هناك بعض أنواع الخلاف لا يسعه الخروج من الخلاف، ولكن في باب الوضوء ليس هناك مسألة لا يسع الخروج منها، أي أن الخلاف ما بين واجب ومستحب، والأفضل في مثل هذه المسائل الخروج من الخلاف (مثل الدلك، التسمية، المضمضة والاستنشاق). أما المسائل التي ما بين واجب ومحرم أو بين (شرط ومبطل) لا يسع الخروج من الخلاف، لا بد فيها من الترجيح، مثال ذلك: الاعتداد بالفاتحة أم بالركوع؛ لأن من العلماء من يقول له: صليت خمسة، والآخر يقول: صليت ثلاثة.`, },
      { q: `التسمية في الوضوء: حكمها وصيغتها`, p: `37–38`,
        n: `ذكرها النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `الحنابلة (في رواية مرجحة عندهم): التسمية باللسان شرط في صحة الوضوء أو ركن من أركانه، فمن قال إن التسمية واجبة فمعناه عنده أن الذي لم يسمِّ يكون وضوؤه باطلًا، لقوله ﷺ: «لا وضوء لمن لم يذكر اسم الله عليه».`,
        s: `يعني بذلك أن هناك خلافًا في التسمية؛ فالحنابلة عندهم رواية مرجحة (أن التسمية باللسان شرط في صحة الوضوء أو ركن من أركانه) فلم يقل أحد بواجبات ليست شروطًا أو ليست أركانًا [الوضوء ليس فيه عند الحنابلة التقسيم الذي في الحج والعمرة والصلاة من أركان وواجبات ومستحبات] [أما الوضوء فالركن عند العلماء هو الواجب أو شرط من شروطه]، فمن قال التسمية واجبة فمعناه أن الذي لم يسمِّ يكون وضوؤه باطلًا لقوله ﷺ: «لا وضوء لمن لم يذكر اسم الله عليه» (ت 25، جه 397، انظر صحيح الترغيب والترهيب 202)، ولقوله ﷺ: «ثم قال: توضؤوا باسم الله، فرأيت الماء يخرج من بين أصابعه ﷺ» صححه ابن حبان، قال الألباني: صحيح. والمشروعية لا نزاع فيها بين العلماء، والكلام على الوجوب، والصحيح في المسألة أن ذكر اسم الله الواجب هو النية؛ لأن هذا قد ذكر الله بقلبه، وذلك هو المقتضي الذي جعلنا نحمل حديث «لا وضوء لمن لم يذكر اسم الله عليه» [على نزاع في تصحيحه، وقد جمعوا له طرقًا كثيرة صححه بها كالشيخ الألباني، والإمام أحمد احتج به مصححًا له] فحملناه على الذكر بالقلب (النية) تقريبًا إلى الله ﷻ؛ ولأن النبي ﷺ في مقام التعليم للرجل الجاهل الذي لم يحسن الصلاة أمره بالوضوء فقال: «إنها لا تتم صلاة أحدكم حتى يسبغ الوضوء كما أمره الله ﷻ، فيغسل وجهه ويديه إلى المرفقين ويمسح برأسه ورجليه إلى الكعبين»، فلم يزد على ما في الآية وهي بيِّنة، ومن هنا قلنا إن هذه الآية وهذا الحديث وهو في مقام التعليم للجاهل ولا يجوز تأخير البيان عن وقت الحاجة، وقد أمره بالواجبات التي أتى بها والتي لم يأتِ بها؛ فأقل شيء أن هذا الرجل كان قائمًا ومع ذلك أمره بالقيام [إذا قمت إلى الصلاة] وأمره باستقبال القبلة، وبالقطع كان مستقبل القبلة، فدل ذلك على أن كل ما في هذا الحديث هو مما لا تصح الصلاة إلا به، ومن هنا نقول: إن هذا الوضوء بأن يفعل ما في الآية يجزئ وتصح به الصلاة، فهو دليل صارف للوجوب، ونقول الأمر بالتسمية للاستحباب. و(لا وضوء) أي كاملًا لمن لم يذكر اسم الله — وهذا الحمل ضعيف؛ لأن الأصل في النفي إما نفي الكمال الواجب أو نفي الإجزاء — أصلًا —، أما نفي حقيقة الشيء أو نفي الكمال المستحب فهذا غير مستعمل، وهذا غير ظاهر؛ لأن لو صح ذلك لصح نفي الصلاة والصيام بل والإيمان عن كل الأمة؛ لأن النبي ﷺ أكمل في ذلك كله، ولصح أن يقال (لا إيمان للأمة) أي لا إيمان كاملًا، ولا نزاع في بطلان هذا وفي عدم جواز إطلاقه، ولصح أن يقال بالمعنى المجازي (الناس لا يصلون)؛ لأن هناك صلاة أكمل، وهذا كلام باطل. ولذلك فالصحيح في قاعدة النفي لو شيء نفي حقيقته فأقرب شيء له هو نفي الإجزاء أو نفي الصحة أو نفي الكمال الواجب على الأقل، فالراجح حمل الحديث على معنى الذكر، وأن الذكر بالقلب ذكر حقيقي بل هو أصل الذكر، فأصل كلمة [تذكر، اذكر كذا] وهو أن يقع في قلبه هذا الأمر ثم يعبر عن ذلك باللسان، ولا شك أنه لو قال [قل كذا] فلا بد أن يقول ذلك بلسانه، وأما إذا قال [اذكر كذا] («لا وضوء لمن لم يذكر اسم الله») فهذا قد ذكر اسم الله حين نوى بقلبه التقرب إلى الله ﷻ، فترك بيان التسمية في مقام التعليم للجاهل مع قاعدة تأخير البيان عن وقت الحاجة لا يجوز جعلنا نصرف (اسم الله) في الوضوء في الحديث إلى الذكر بالقلب دون ذكر اللسان، وهذا أقوى ما يستدل به الجمهور على عدم وجوب التسمية. ومن هنا نقول إن (الوضوء المنفي) أن من لم ينوِ بقلبه فإنه ما توضأ ووضوؤه باطل. أما المستحب أن يقول بلسانه، نعم، فيقول: يحرص على التسمية خروجًا من الخلاف مع الحنابلة وطائفة من أهل الحديث ممن يقول إن من لم يسمِّ وضوؤه باطل، والمقصود بالنية أن ينوي التقرب إلى الله بأن هذا وضوء، ليس أنه يغسلها تبردًا أو نظافة، لا، فإنه يتعبد لله بذلك. هناك قولان للعلماء في مسألة أن التسمية واجبة مطلقًا أم أنها واجبة مع الذكر فقط [إذا تذكر]، والحديث ظاهره إذا قلنا إن التسمية معناها النطق ظاهره أنها واجبة مع الذكر والنسيان، وإذا حملناه على القلب فنحن نقول به على إطلاقه، وهو أنه إذا نسي أن ينوي لم يصح وضوؤه — فإذا غسل ولم يتقرب إلى الله بأن هذا وضوء ليستبيح به الصلاة أو ليرفع الحدث فلا يصح وضوؤه —. الغرض المقصود أن هناك خلافًا في التسمية فينبغي أن يأتي بها بلسانه، والسنة في ذلك أن يقول كما قال ﷺ: «توضؤوا باسم الله» فيقول: (بسم الله)، ومن المتأخرين من يقول: (بسم الله الرحمن الرحيم)، ولكن الصحيح أن يقول (بسم الله)، وبعض العلماء من بدع قول (بسم الله الرحمن الرحيم) في هذا المقام.`, },
      { q: `النية في الوضوء`, p: `38`,
        n: `ذكرها النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `الحنفية: الوضوء يصح بغير نية، فلو انغمس في ماء من غير نية صح وضوؤه بذلك.`,
        s: `الخلاف فيه للحنفية، فهم يرون أن الوضوء يصح بغير نية، أما الجمهور فقد احتجوا بأن الوضوء عبادة مقصودة، والدليل على ذلك كثرة الأدلة في فضل الوضوء وثوابه، وأن غسل هذه الأعضاء بالنسبة إلى الحدث غير معقول المعنى (أي غسل الوجه واليدين لخروج الريح)، فهذا أمر تعبدي ولا تصح العبادة إلا بنية، وقول الجمهور هو الصحيح لعموم قول النبي ﷺ: «إنما الأعمال بالنيات»، وللأدلة التي ذكرت فيها فضل الوضوء وفضل غسل الأعضاء عضوًا عضوًا، وفضل خروج الذنوب والخطايا مع آخر قطرة ماء مع كل عضو من الأعضاء؛ إذًا فهذا ليس مرتبطًا بمعنى معقول في الحدث. أما غسل النجاسة فمعقول المعنى، لذلك يصح بغير نية على الصحيح وهو قول الجمهور، وكالاستنجاء فموضع إزالة النجاسة من البدن في موضع الاستنجاء أو في غيره معقول المعنى كالنظافة والتطهر، وهي طهارة محسوسة، أما الوضوء فطهارة غير معقول المعنى، لا تدرك العقول الإنسانية من غير نور الوحي فضل هذه الأعضاء أن تُغسل، فتغسل اليد لخروج الريح أو لحصول النوم أو لخروج البول من محله فيغسل وجهه ويمسح برأسه. ولذلك نقول إن إزالة النجاسة لا يلزم فيها نية، فلو أنه لم يُخبر الغاسل أو الغاسلة أن هذا الثوب به نجاسة فلم ينوِ إزالة النجاسة ولكن أُزيلت فهذا يصح ويكون قد تطهر، وكذلك لو وضع الثوب في مكان ونزل عليه المطر أو أتى عليه ماء البحر وأزال النجاسة بالكلية من غير قصد صح ذلك وصحة الصلاة فيه، وأما الوضوء فليس كذلك، فالوضوء لا بد فيه من نية، والخلاف فيه كما ذكرنا للحنفية.` },
      { q: `مسح الأذنين في الوضوء`, p: `38–39`,
        n: `ذكره النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `من يوجب استيعاب مسح الرأس يوجب مسح الأذنين على القول بأنهما من الرأس.`,
        s: `على القول الصحيح أن الأذنين من الرأس، وعلى قول من يوجب استيعاب مسح الرأس يجب أن يمسح الأذنين، والصحيح أن الأذنين من الرأس وأن السنة استيعاب مسح الرأس والأذنين، ولكن على الراجح أن هذا ليس من الأركان (ليس من واجبات الوضوء). وأما استيعاب مسح الرأس فالخلاف فيها أشهر، والاستيعاب أحوط، والراجح أن مطلق المسح يجزئ.` },
      { q: `دلك الأعضاء في الوضوء والغسل (تكملة)`, p: `39`,
        n: `ذكره النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `المالكية: لا يتم مسمى الغسل إلا إذا دلك الأعضاء.`,
        s: `الخلاف فيه للمالكية فقد قالوا: لا يتم مسمى الغسل إلا إذا دلك الأعضاء، وظاهر أحاديث الغُسل أنه أفاض على سائر بدنه الماء؛ والإفاضة: جريان الماء، ويسمى ذلك غسلًا، فالصحيح أن دلك الأعضاء مستحب، ولا يلزم دلك الأعضاء بل يكفي جريان الماء على أعضاء الوضوء. والفرق بينه وبين المسح أن المسح عبارة عن بلل لليد ومباشرتها لحصول البلل على الأعضاء من غير أن يلزم جريان الماء (بتقطير اليد ماءً)؛ فالقدر المجزئ من الغسل هو جريان الماء على أعضاء الوضوء، وأما الدلك فمستحب، ولو دلك بدون جريان الماء لا يصح الغسل، ولو جرى بدون دلك صح الغسل على الراجح، والأحوط أن يغسل بجريان الماء مع الدلك.` },
      { q: `الموالاة (التتابع) في الوضوء`, p: `39`,
        n: `ذكرها النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `المالكية: لا يلزم التتابع.`,
        s: `الخلاف فيه للمالكية الذين قالوا لا يلزم التتابع، والصحيح قول الشافعية والحنابلة أنه فرض وواجب؛ لأن «النبي ﷺ رأى رجلًا يصلي وفي ظهر قدمه لمعة قدر الدرهم لم يصبها الماء، فأمره النبي ﷺ أن يعيد الوضوء والصلاة» (د 175) [قال الألباني: صحيح]، فدل ذلك على وجوب تتابع غسل الأعضاء، والواو تقتضي الجمع، ولأن النبي ﷺ أمره بأن يعيد الوضوء، وهو دليل على أنه لا بد من الموالاة والتتابع. والشرع رد الموالاة والتتابع إلى العرف [فمتى نقول فقدت الموالاة أو فقد التتابع فهو أمر عرفي]، فالشرع لم يحدده، فمسألة أنه على قدر جفاف الأعضاء فإن قدر جفاف الأعضاء قدر يسير، وهو كلام غير منضبط، بل مرده إلى العرف [حتى يقال أن هذا قد غسل هذه الأعضاء مع بعضها] أو أنه قد طال الفصل — عرفًا —.` },
      { q: `الترتيب في الوضوء`, p: `39`,
        n: `ذكره النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف.`,
        o: `الشافعية: الترتيب واجب؛ لإدخال الممسوح بين المغسولين.`,
        s: `الخلاف فيه للشافعية، والصحيح استحباب الترتيب لعدم وجود ما يدل على وجوبه، والواو كما ذكرنا تقتضي مطلق الجمع والعطف، وهو لا يلزم منها الترتيب، وقول الشافعي بإدخال الممسوح بين مغسولين لا بد أن يكون لعلة وتقرر أن هذا أمر تعبدي مشروع، والخلاف في درجة المشروعية: واجب أم مستحب؟ فلو قلنا باستحباب الترتيب فيكون هناك علة مذكورة في الآية.` },
      { q: `الماء الذي يُتوضأ به عند الخلاف (تحصيل ماء طهور بالإجماع)`, p: `39`,
        n: `ذكره النووي فيما ينبغي أن يحرص عليه المتوضئ خروجًا من الخلاف: «وتحصيل ماء طهور بالإجماع».`,
        o: NO_O,
        s: `فهناك خلاف في الماء المستعمل، وكذا الماء القليل الذي وقعت فيه نجاسة، فالاحتياط هو تحصيل ماء طهور بالإجماع بحيث لا يختلف فيه العلماء، وبهذا يكون قد أحسن الوضوء على جميع الأقوال.` },
      { q: `الترخص بالاختلاف وتتبع الرخص والتلفيق بين المذاهب`, p: `39–40`,
        n: `قال النووي: «ولا يترخص بالاختلاف».`,
        o: `بعض المتأخرين (ومنهم بعض المعاصرين وبعض المفتين ولجنة الإفتاء المصرية وغيرها): يجيزون التلفيق والأخذ بالأيسر لمجرد التشهي، ويقولون إن إجماع ابن عبد البر على المنع غير صحيح لوجود خلاف بعده.`,
        s: `مسألة الترخص بالاختلاف: هل الاختلاف نفسه رخصة لمجرد وقوع الاختلاف؟ هذا المذهب مذهب مرجوح بل باطل، فإنه يترخص لمجرد الاختلاف؛ فالواجب على الإنسان إذا كان هناك مسألة مختلف فيها أن يعمل فيها بمقتضى علمه: فإن كان عالمًا وجب عليه أن يجتهد ويعمل بالراجح، وإن كان طالب علم مميز قادر على الترجيح بعد جمع الأدلة وجب عليه ذلك، وأما إذا كان عامي غير قادر على الترجيح فعليه أن يسأل أهل العلم الذي يثق فيهم. هذا أصح الأقوال في المسألة، بل الصواب أنه لا يسع المقلد عند الاختلاف أن يأخذ ما يشتهي من المذاهب، ولا يلزمه الأخذ بالأشد ولا بالأخف، بل يلزمه أن يقلد الأوثق في نفسه. ورغم وجود خلاف كبير في هذه المسألة إلا أن غير هذا القول الذي ذكرناه يترتب عليه من الفساد والفتن ما لا يعلمه إلا الله؛ فالقول الذي نختاره ونصوبه هو أن المقلد يلزمه أن يسأل أهل الذكر، فإن اختلفوا عليه فيأخذ بقول أوثقهم في نفسه [والأوثق هو الأعلم الأورع إن وجد، وإلا فالأعلم في زمن قلة الفتن والأورع في زمن كثرة الفتن] وما يفتيه به يأخذ به ويلتزمه، ولا يسعه أن يتركه إلى غيره من غير مُرجِّح. فمسألة الترخص بالاختلاف فقد نقل ابن عبد البر قول العلماء: (أن من تتبع رخص العلماء اجتمع فيه الشر كله)، ونقل إجماع السلف المتقدمين على المنع من ذلك، ولذلك قلنا في هذه المسألة أن هذا هو الصواب، وإن كان بعض المتأخرين ذكر خلافًا في ذلك كفتاوى لجنة الإفتاء المصرية وغيرها، فيرجحون جواز التلفيق لمجرد التشهي والبحث عن الأخف، ويقولون إن الإجماع الذي نقله ابن عبد البر غير صحيح لوجود علماء قالوا بذلك، فنقول: الخلاف المذكور بعد الإجماع الأول الذي ذكره ابن عبد البر فهو غير قادح فيه، فإن المتأخرين الذين قد أجازوا التلفيق من غير حجة وأجازوا التلفيق بأن يأخذ من هذا المذهب ويأخذ من هذا المذهب. وهو يطلق على جمع أقوال من مذاهب متعددة في مسائل مختلفة، هذا التلفيق على نوعين: 1. نوع يكون بترجيح طالب علم أو عالم قد انتسب في بداية تعلمه ونشأته أو حتى إفتائه لمذهب ثم وصل إلى مرتبة الاجتهاد والترجيح حتى ولو في بعض المسائل فأخذ بمذهب يخالف مذهب إمامه للدليل الذي صار من أهل الترجيح، فهذا تلفيق مشروع بل هو الواجب ولا يذم على ذلك؛ بمعنى أنه نشأ حنبليًّا أو شافعيًّا ثم ترجح له بالدليل لأنه صار من أهل الاجتهاد عمومًا أو في مسألة أو في باب بأن جمع أدلته وعنده القدرة على معرفة قواعد الترجيح (قواعد الأصول) وقواعد الاستنباط فعرف بالأدلة أن هذا المذهب مرجوح في هذه المسألة وأن المذهب الآخر هو الراجح لزمه أن يأخذ بالراجح، ولا يسعه أن يقلد في تلك الحال لأنه صار من أهل العلم وبذل جهده وعرف الحق بعد البحث والتحري، فلا ينبغي أن يخالفه فقد أمر الله باتباع البينات. 2. بأن يجمع بين أقوال المذاهب المختلفة بغير دليل، وللأسف هذا رأي طوائف من المعاصرين سواء المنتسبين إلى التسهيل والترخيص على الناس، أو بعض المفتين يقررون ذلك، أو بعض الاتجاهات الإسلامية تجعل مذهبها ذلك بأن كل مذهب وقول هو معتبر طالما قال به عالم ويجوز أن يأخذ به، وهذه الطريقة في التلفيق هي التي نقل الإجماع فيها ابن عبد البر على عدم جوازها، وخصوصًا أن هذا الأمر إذا تم من عالم فهو أقبح؛ فإن الكلام في حق المقلد أنه لا يجوز فيما بال في حق عالم قادر على الاستنباط وقادر على الترجيح أن يأخذ بالأسهل من المذاهب على الناس ويفتيهم بهذا الكلام، بهذه الطريقة فهذا من أعظم المنكرات، وقد يسأل بعض المستفتين الشيخ ويقول له: ابحث لنا عن مذهب أيسر، وهل هناك قول آخر؟ وهذه طريقة يتبعها بعض المفتين فهو لا يرجح أو يرجح ومذهبه مثلًا في مسائل الطلاق مثلًا أن الطلاق البدعي واقع، ويعتقد بطلان مذهب شيخ الإسلام ابن تيمية، ولكن يقول: شيخ الإسلام إمام كبير فلنلفق بقوله ونيسر على الناس؛ بعض الناس يقولون له: هذه الطلقة الثالثة، فيقول لهم: خذوا بقول شيخ الإسلام، يقولون له: هذه الطلقة الثانية فيفتي بقول الجمهور! فهذه أعاجيب من الباطل التي لم يقل بها عالم. والصحيح أن هذا إجماع في حق المقلد والعالم وطالب العلم، أعني بذلك الأخذ من المذاهب بالتشهي، فهذا هو التلفيق الباطل.` },
      { q: `تكفير الطهارة والصلاة للذنوب: الصغائر دون الكبائر، وجواب «إذا كفَّر الوضوء فماذا تكفر الصلاة...»`, p: `41–42`,
        n: `قوله ﷺ «كانت كفارة لما قبلها من الذنوب ما لم يؤت كبيرة وذلك الدهر كله»: معناه أن الذنوب كلها تُغفر إلا الكبائر فإنها لا تُغفر، وليس المراد أن الذنوب تُغفر ما لم تكن كبيرة، فإن كانت لا يُغفر شيء من الصغائر؛ فإن هذا وإن كان محتملًا فسياق الأحاديث يأباه. قال القاضي عياض: هذا المذكور في الحديث من غفران الذنوب ما لم تؤتَ كبيرة هو مذهب أهل السنة، وأن الكبائر إنما تكفرها التوبة أو رحمة الله تعالى وفضله. وقد يقال: إذا كفَّر الوضوء فماذا تكفر الصلاة؟ وإذا كفرت الصلاة فماذا تكفر الجمعات ورمضان؟ وكذلك صوم يوم عرفة كفارة سنتين ويوم عاشوراء كفارة سنة؟ وإذا وافق تأمينه تأمين الملائكة غُفر له ما تقدم من ذنبه؟ والجواب ما أجابه العلماء: أن كل واحد من هذه المذكورات صالح للتكفير، فإن وجد ما يكفره من الصغائر كفره، وإن لم يصادف صغيرة ولا كبيرة كُتبت به حسنات ورُفعت به درجات، وإن صادفت كبيرة أو كبائر ولم يصادف صغيرة رجونا أن يخفف من الكبائر.`,
        o: `احتمال في تفسير الحديث: أنه إذا وُجدت الكبائر فلا يُغفر شيء من الصغائر.`,
        s: `(«فإنها لا تغفر»: قصده أنها لا تُغفر بذلك.) (فإن كانت) أي فإذا وجدت الكبائر فلا يُغفر شيء من الصغائر؛ فهناك احتمالان في تفسير هذا الحديث: 1- الصغائر تغفر بهذا والكبائر تبقى. 2- لا تغفر الصغائر إلا إذا اجتنب الكبائر. وهذا الاحتمال الثاني قال عنه [أن سياق الأحاديث تأباه]، فالأحاديث تدل على مغفرة الخطايا (الصغائر) بالوضوء، أما الكبائر فلا بد لها من توبة. وقول القاضي «إنما تكفرها التوبة أو رحمة الله»: بمعنى أنه إذا لم يتب فهو في المشيئة، إن شاء الله أن يرحمه وغفر له غفر له. وجواب العلماء (أن كل واحد من هذه المذكورات صالح للتكفير ...) هذا من أحسن الكلام.`,
        f: [
          `(ص41) على قوله ﷺ «غُفر له ما بينه وبين الصلاة التي تليها» أي التي بعدها: أي إذا صلاها.`,
          `(ص41) على قوله «وفيه لطيفة أخرى: وهو من رواية الأكابر عن الأصاغر، فإن صالح بن كيسان أكبر سنًّا من الزهري»: وهذا يدل على تواضع السلف، وأن الكبير كان يتتلمذ على يد الصغير طالما سمع حديثًا عنه فيذهب ويسمعه منه ويرويه عنه، فلا يتكبر أن يروي عن من هو أصغر منه، وهذه فضيلة من فضائل العلم والإخلاص فيه وعدم الاستنكاف أن يتعلم الإنسان ولو ممن هو أصغر منه.`,
          `(ص41) على قوله «ما لم يؤتِ كبيرة» (وفي رواية: ما لم يأتِ): وهذا هو الضبط الصحيح لها؛ لأنه لو كان (يؤتِ) [ما لم يؤتِ كبيرة] يجوز أيضًا؛ لأن هذا تأنيث مجازي، أما [ما لم يأتِ كبيرة] فهذه [ما لم يأتِ كبيرة] فيؤتيها أي يعطيها، والصحيح [ما لم تؤتَ كبيرة] أو [ما لم يؤتَ كبيرة]، فالتأنيث المجازي يجوز ترك علامة التأنيث فيه.`,
          `(ص43) على قوله «وفيه دلالة للشافعي ومن وافقه في أن المستحب في الرأس أن يمسح ثلاثًا»: ذكرنا سابقًا قول ابن القيم رحمه الله أن الصحيح (أي هذا الحديث) غير صريح، فقد قال [توضأ ثلاثًا ثلاثًا]، فليس صريحًا في أن الرأس ثلاثًا؛ لأنه يصح ذلك على الأغلب، فأغلب الأعضاء تُغسل ثلاثًا فيصح أن يُقال [توضأ ثلاثًا ثلاثًا]، والصريح غير صحيح. ويمكن أن يُقال — كلام الشيخ الألباني في تصحيحه للأحاديث رغم أنها شاذة عند جمهور المحدثين أنه مسح برأسه ثلاثًا — فهذا التصريح ضعيف عند الجمهور — يفعل أحيانًا؛ لأن الروايات مصرحة أنه مسح رأسه مرة واحدة في الصحيحين.`,
          `(ص43) على قوله «وعنده رجال من أصحاب النبي ﷺ ... قالوا: نعم»: هذا دليل على التعليم بالفعل والإقرار، فقد استنطق الصحابة ليقروا بذلك ليكون أوقع في نفوس الحاضرين.`,
          `(ص43–44) على استدراك الدارقطني على إسناد «وكيع عن سفيان عن أبي النضر عن أبي أنس»: وهذا مثال لما يستدركه الدارقطني على مسلم؛ فهذا الكلام لا يقدح في صحة الحديث بداية، فمسلم ذكرها في آخر الأسانيد وإلا فالجملة ثابتة بلا شك. وكلام الدارقطني مصيب في استدراكه هذا، ولكن هذا لا يقدح في الحديث، فهو يقول له: كيف أتيت بهذا الإسناد وقد كان يكفيك الإسناد الآخر؟ فلا يصلح أن تقول شرطي الصحيح وتُدخل هذا الإسناد في كتابك؛ لأن هذا وهم والوهم لا ينبغي أن تضعه في الصحيح، لكن المتن نفسه ثبت وصح.`,
          `(ص44) على قوله ﷺ «ما أدري أحدثكم بشيء أو أسكت» واحتمال أنه لا يدري هل ذكره مصلحة ثم ظهرت له المصلحة: وهذا دليل على وقوع الاجتهاد منه ﷺ.`,
          `(ص45) على قوله «فإنه دال على أن من اقتصر في وضوئه على طهارة الأعضاء الواجبة وترك السنن والمستحبات كانت هذه الفضيلة حاصلة له»: فقد يحتج به من يقول أن الآية هي النص، والآخرون يجيبون بأن الله كتب عليه في الكتاب أو في السنة، لكننا سوف لا نحتج بهذه الرواية بمفردها، بل سنحتج بترك الرسول ﷺ الزيادة على الآية في مقام التعليم.`,
          `(ص45) على قوله «وفي هذا الحديث الحث على الإخلاص في الطاعات وأن تكون متمحضة لله تعالى»: («لا ينهزه إلا الصلاة») أي لله ﷻ.`,
        ] },
    ],
  },
  {
    title: `باب الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفرات لما بينهن ما اجتُنبت الكبائر (ص46–49)`,
    items: [
      { q: `قول «رمضان» من غير إضافة «شهر» إليه`, p: `46`,
        n: `قوله ﷺ «ورمضان إلى رمضان كفارة لما بينهما» فيه جواز قول رمضان من غير إضافة شهر إليه، وهذا هو الصواب، ولا وجه لإنكار من أنكره، وستأتي المسألة في كتاب الصيام — إن شاء الله تعالى — واضحة مبسوطة بشواهدها.`,
        o: `بعضهم: «رمضان» اسم من أسماء الله فلا بد أن يُقال: شهر رمضان.`,
        s: `فالبعض قد قال إن [رمضان] اسم من أسماء الله فلا بد أن يقول شهر رمضان، فلم يثبت أن هذا اسم من أسماء الله، ولم يثبت نهي، والأحاديث في ذلك ضعيفة جدًّا، ومع ثبوت الأحاديث الصحيحة المصرحة بإطلاق (رمضان) من غير كلمة (شهر).`, },
      { q: `بمَ تُدرك الركعة: بالركوع أم بقراءة الفاتحة؟ (فتوى)`, p: `47`,
        n: NO_N, o: NO_O,
        s: `القول الراجح في الاعتداد بالركعة: بالفاتحة إن شاء الله؛ وعمومًا الاستدلال الأصلي «لا صلاة لمن لم يقرأ بأم القرآن» (مسلم)، والركعة تسمى صلاة.` },
      { q: `حكم الوضوء في دورة المياه (فتوى)`, p: `47`,
        n: NO_N, o: NO_O,
        s: `جائز، فيزيل النجاسة فيسمي، وإما يخرج فيسمي ويدخل.` },
      { q: `الوضوء بالماء المغصوب والمسروق (فتوى)`, p: `47`,
        n: NO_N, o: `اشترط بعضهم في الوضوء الماء المباح.`,
        s: `أي أن الماء المغصوب والمسروق ليس فيه انفكاك جهة، بخلاف الإناء المغصوب الذي فيه ماء مباح ففيه انفكاك جهة. والراجح أن الجهة منفكة في الحالتين (فيصح الوضوء مع الإثم)، ويضمن مثل هذا الماء لمن غصبه منه.` },
      { q: `المقلد إذا رأى مسألة واضحة جدًّا خلاف قول شيخه الأوثق (فتوى)`, p: `47`,
        n: NO_N, o: NO_O,
        s: `يأخذ بقول شيخه؛ لأنك افترضت أنه مقلد، فهذا الوضوح وضوح ليس له معنى، أما إذا كان طالب علم مميز بمعنى أنه جمع الأدلة في الباب وعنده القدرة على الترجيح فيكون هذا هو الذي يقال عليه رآها واضحة، والمقلد رؤيته ليس لها اعتبار.` },
      { q: `رؤية المرأة فجأة ومعنى «إن المرأة تُقبل في صورة شيطان» (فتوى)`, p: `47`,
        n: NO_N, o: NO_O,
        s: `قول النبي ﷺ: «إن المرأة تقبل في صورة شيطان وتدبر في صورة شيطان، فإذا أبصر أحدكم امرأة فليأت أهله، فإن ذلك يرد ما في نفسه»، وفي مسلم أيضًا: «إذا أحدكم أعجبته المرأة فوقعت في قلبه فليعمد إلى امرأته فليواقعها فإن ذلك يرد ما في نفسه». هل الرؤية هذه رؤية فاجأة؟ نعم فهي في أول نظرة، وليس شرط أنها رؤية فاجأة يترتب عليه ما يعجبه، فربما نظرة فاجأة فلم تعجبه، فليصرف بصره أيضًا، ولكن هنا إذا رأى ما يعجبه فليأت أهله، وإن رأى عمدًا فليأت أيضًا أهله؛ لأن العلة المذكورة علة موجودة وهي أزكى للنفس، وعليه أن يتوب إلى الله ﷻ.`,
        f: [
          `(ص47 — من الفتاوى) عن استدراكات الإمام الدارقطني على الصحيحين: استدراكات الإمام الدارقطني الإمام ابن حجر رد عليها كلها، وهذا في استدراكه على البخاري؛ ولذلك الراجح أن استدراكاته على البخاري لا تقدح في صحة الأحاديث إلا ما كان من جنس المقلوب، وهو أيضًا قد روي في البخاري برواية أخرى صحيحة كرواية: (وأما النار فيبقى فيها فضل حتى ينشئ الله لها خلقًا) هذه الرواية ضعيفة فعلًا، ولكن الحديث ثابت في الصحيحين برواية (وأما الجنة)؛ ولكن في مسلم ربما توجد أحاديث لا تتجاوز عددها أصابع اليدين قد أصاب الدارقطني استدراكاته فيها. وفائدة هذه المسألة: أن استدراكات الدارقطني أو غيره خارجة عن محل الإجماع، فالذي يطعن فيما سوى هذه الأحاديث والأسانيد يكون مبتدعًا لأن الأمة تلقتها بالقبول، ولكن الذي يتكلم في بعض الأحاديث التي استدركها الدارقطني وغيره فهذا إنما يكون اجتهاد في المسألة، ولذلك قلنا إن هذا يفيد العلم النظري لأنه مجمع عليه والمخالف ضال مبتدع.`,
        ] },
      { q: `هل ترث بنت العم مع إخوتها من ابن عمها؟ ومن مات وليس له ولد ولا والد ولا إخوة فورثه أولاد عمه، هل ترث أختهم؟ (فتوى)`, p: `47`,
        n: NO_N, o: NO_O,
        s: `بنت العم لا ترث مع إخوتها في ابن عمها، فما بقي فلأولى رجل ذكر. ورجل مات وليس له والد ولا ولد ولا إخوة ولا أخوات يرثه أولاد عمه، ولا ترث أختهم بالاتفاق.` },
      { q: `الأمر بالتسمية في حديث «توضؤوا باسم الله»: أليس يفيد الوجوب؟ (فتوى)`, p: `47–48`,
        n: NO_N, o: NO_O,
        s: `(قال: فرأيت النبي ﷺ وضع يده في الإناء الذي فيه الماء ثم قال: «توضؤوا باسم الله»، فرأيت الماء يفور بين أصابعه والقوم يتوضؤون حتى توضؤوا عن آخرهم) ابن حبان. لكن (بسم الله) هو ﷺ الذي بدأ، وهذا يُحتج به على مشروعية التسمية لأنه لم يقل لكل واحد أن يذكر اسم الله، فهو فقط ﷺ الذي قال (بسم الله)، مثل («اغزوا باسم الله») فهل معناها أن كل الناس في الغزو تقول بسم الله؟ لا.` },
      { q: `دراسة مذهب فقهي معين (التمذهب) (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `دراسة مذهب معين (التمذهب) ليس بواجب، والحقيقة أن طالب العلم في بداية طلبه أو العامي لو قال أنا مذهبي كذا فليس مذهبًا له، فيلزمه على الأقل أن يعرف معظم المذهب، فدراسة مذهب معين لا يضر.` },
      { q: `إذا اختلف المشايخ في مسألة فبأي قول يعمل المقلد؟ (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `كما قلنا يقلد أوثقهم في نفسه في هذا الباب، ولا مانع أن يكون عنده أوثقية في أبواب مختلفة، وعليه أن يجتهد في هذه الأوثقية؛ فكما قلنا (الأعلم الأورع) إذا كان هذا الأمر متوفرًا، فإذا لم يجد فالأعلم في زمن قلة الفتن — فإذا كان ليس عنده ورع فلا يصلح أن يُستفتى، رجل ليس عنده علم لا يصلح أن يُستفتى — فنحن نقول الأفضل الأعلم الورع إذا كان في مسائل فيها غموض ونحو ذلك ومأمون عليهم الفتنة، وأما في زمن الفتن والشبهات والشهوات كثيرة فنقول الأورع العالم.` },
      { q: `الموالاة والترتيب في الوضوء، ومن توضأ مبتدئًا من أي ركن (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `قلنا في الترتيب والموالاة: أن الموالاة واجبة والترتيب مستحب. وهل يصح وضوء رجل قد توضأ مبتدئًا من أي ركن؟ نعم يصح، ولكن يلزمه أن يوالي (فيغسل الأعضاء وراء بعض ولا يفصل بينها بفاصل كبير عرفًا)، فقد يكون مرتبًا وليس فيه موالاة، وهذا كما قلنا أن الواو تفيد مطلق الجمع (مطلق العطف)، وإدخال ممسوح بين مغسولين يقتضي استحباب الترتيب.` },
      { q: `البيع والشراء في مكان الوضوء داخل المسجد (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `نعم يجوز (أي في مكان الوضوء لأنه ليس من المسجد).` },
      { q: `من توضأ لقراءة القرآن ولم ينوِ الوضوء للصلاة: هل يصلي به؟ (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `الراجح أنه يجزيه لأنه نوى رفع الحدث.` },
      { q: `المقلد إذا أُقيمت عليه الحجة بالدليل فقال: شيخي كبير وأثق به (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `إذا كانت المسألة من أدلتها البينات من الكتاب والسنة مثل عبادة القبور فقد قامت عليه الحجة، وأما في مسألة اجتهادية خفية بالنسبة له فالأمر فيه احتمال، ولكن مسألة ظاهرة — من المجمع عليها مثل دعاء الأموات والذبح والنذر لهم فتأتي له بآية من كلام الله — فلا عبرة بكونه يقلد غيره في الشرك بالله.` },
      { q: `دورات المياه الملحقة بالمسجد وقضاء الحاجة فيه (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `(السؤال: يلزم من قولكم أن دورات المياه ليست من المسجد طالما يفصل بينها باب، أن الضريح إذا كان يفصل بينه وبين المسجد باب فهو خارج المسجد؟ وحتى لو هو خارج المسجد وهل النبي ﷺ شرط أنه لا بد أن يكون الضريح داخل المسجد؟ أم أنه قال: «لا تتخذوا القبور مساجد» فهذا يشمل أنه بجانبه أو أنه مفتوح عليه باب أو الباب مغلق.) وهل تعتقد أنه يجوز قضاء الحاجة في المسجد؟ فأنت بذلك ترتكب منكرًا كلما تدخل، فلو أن دورة المياه بداخل المسجد فإن قضاء الحاجة فيها محرم؛ لأنه في الحديث: (فتركوه حتى بال، ثم إن رسول الله ﷺ دعاه فقال له: «إن هذه المساجد لا تصلح لشيء من هذا البول ولا القذر، إنما هي لذكر الله ﷻ والصلاة وقراءة القرآن») مسلم، فالبصق حرام، ودورة المياه موجودة لهذه الأغراض أم لا؟!` },
      { q: `حكم أخذ مني الرجل ووضعه في رحم زوجته (فتوى)`, p: `48`,
        n: NO_N, o: NO_O,
        s: `لا بأس بذلك، فالحاجة داعية إلى مثل ذلك.` },
      { q: `حكم مقاطعة المنتجات اليهودية (فتوى)`, p: `48–49`,
        n: NO_N, o: NO_O,
        s: `علمًا بأن بعض الناس بدأ يعلق لافتات كثيرة في المساجد من أجل ذلك؟ الأولى أن يعلقوا (قاطعوا الذنوب وقاطعوا المعاصي والمحرمات)، ثم أين هي المنتجات اليهودية؟ لا نعرف، فليست مجرد علامة تجارية تقاطع وانكسر؛ فصاحب الشركة (مالكها) مسلم والعمال مسلمين فيتضرروا وأصيبوا وجرحوا، ولو الشركة أُغلقت فهناك عائلات كثيرة جدًّا سوف تتضرر من المسلمين، فهذا الأمر يحتاج إلى دراسة بحيث نتأكد أنها ليست مجرد علامة تجارية بل هي فعلًا مملوكة للكفار، وأن مصلحة المسلمين تتحقق في مقاطعتها، فساعتها نقول إن هذا الأمر مشروع. وفي الحقيقة لا أحد يطالبنا بالتقليد الأعمى لجهلة وهم لم يدرسوا شيئًا وليس عندهم نظر إلى المستقبل، وماذا سيحدث بعد ذلك على المسلمين العاملين فيها ونحو ذلك، وهل صاحبها مسلم أم لا، وما هو التعاقد الذي بينه وبينهم، فلا يعرفوا شيئًا من ذلك، فعلينا أن نعرف، فلا يلزمنا أن نحرم على الناس شيئًا ونحن لا نعرف. ثم إن المقاطعة تكون على الجميع على الصينيين المجرمين الكفرة الذين هم أكفر من اليهود والأمريكان، والهنود المجرمين، ونحن لا نمنع من المقاطعة نهائيًّا، ولكن نقول: إن الأمر يحتاج إلى دراسة، وإلى الآن لا هم يبحثون عن دراسة ولا أحد يبذل جهده في أن يحث في المسألة ويأتي لنا بمعلومات صحيحة عن مصادر ثقات، حتى نثق فيما نأمر به الناس وننهى عنه.` },
      { q: `حكم الصلاة التي تصليها المرأة قبل نزول الدورة رغم نزول السوائل البيضاء (فتوى)`, p: `49`,
        n: NO_N, o: NO_O,
        s: `طالما هناك سوائل بيضاء أو حتى ملونة فصلاتها واجبة إلى أن ترى الدم؛ لأن الكدرة والصفرة بعد الطهر طهر، فلو أنها في طهر ونزل بعد الطهر سوائل بيضاء ولم ينزل بعدُ الدم، فهي ما زالت طاهرة إلى أن ينزل الدم.` },
      { q: `زكاة حلي المرأة إذا بلغ النصاب وهي تلبسه (فتوى)`, p: `49`,
        n: NO_N, o: NO_O,
        s: `الراجح في المسألة وجوب الزكاة حتى ولو كانت تلبسه؛ ففي الحديث: «أن امرأة أتت رسول الله ﷺ ومعها ابنة لها، وفي يد ابنتها مسكتان غليظتان من ذهب، فقال لها: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟» (د 1563) [قال الألباني: حسن]. فإذا بلغ النصاب وجب عليها الزكاة.` },
      { q: `امرأة أسقطت حملًا بعد شهرين ونزل عليها الدم خمسة أيام: دم نفاس أم استحاضة؟ (فتوى)`, p: `49`,
        n: NO_N, o: NO_O,
        s: `لو كان شهرين فسيكون بداية خلق إنسان، والأغلب الأعم أن شهرين قد تكون خلق إنسان، فالراجح أنه ما بين الأربعين يومًا والثمانين يومًا يسأل الطبيب: هل نزل فيه خلق إنسان (أجزاء تدل على ذلك [جنين]) أم لا؟ لأنه ربما يكون شهرين ولكن هذا الجنين مات وهو صغير وترك بالداخل يسمونه (إجهاض مفقود) فبقي في مدة طويلة ميت إلى أن تعيت فنزل بعد ذلك نطفة ليس له حكم الجنين، فالفتوى في هذا الأمر نحتاج فيها إلى رؤية الطبيب.` },
      { q: `هل يجوز للمقلد أن يسأل عالمًا آخر إذا لم يطمئن لجواب العالم الأول؟ (فتوى)`, p: `49`,
        n: NO_N, o: NO_O,
        s: `نعم يجزيه ذلك، ولكنه في النهاية يلزمه تقليد الأوثق.` },
    ],
  },
  {
    title: `باب الذكر المستحب عقب الوضوء (ص49–54)`,
    items: [
      { q: `الذكر المستحب عقب الوضوء، وحصول ثوابه بالقول مع حضور القلب`, p: `54`,
        n: `فيه أنه يستحب للمتوضئ أن يقول عقب وضوئه: [أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدًا عبده ورسوله]، وهذا متفق عليه. وينبغي أن يضم إليه ما جاء في رواية الترمذي متصلًا بهذا الحديث: [اللهم اجعلني من التوابين واجعلني من المتطهرين]. ويستحب أن يضم إليه ما رواه النسائي في كتابه عمل اليوم والليلة مرفوعًا: [سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت وحدك لا شريك لك أستغفرك وأتوب إليك]. قال أصحابنا: وتستحب هذه الأذكار للمغتسل أيضًا.`,
        o: `بعض أهل العلم: يحصل ذلك الثواب لمن قال باللسان حتى ولو لم يستحضر ذلك بالقلب.`,
        s: `زيادة «اللهم اجعلني من التوابين واجعلني من المتطهرين» حديث حسن. والذي يظهر والله أعلم أن (فتحت له أبواب الجنة الثمانية يدخل من أيها شاء) إذا مات عقب ذلك، وطالما كان على تلك الحال في كل مرة فيحصل على هذا الفضل العظيم، فينبغي على العبد أن يكون متوضئًا على الدوام قائلًا هذا الذكر على الدوام؛ لأنه إذا مات على تلك الحال دخل الجنة من أي أبواب الجنة الثمانية شاء. وقوله (ثم يقول): القول هنا ينبغي أن يكون بالقلب واللسان معًا، ولا يكون بترداد اللسان دون استحضار المعنى الذي يتكلم به فيحصل على الثواب، وهذا هو الظاهر في جميع الأذكار بأن يواطئ قلبه لسانه فيجتمعان على الذكر؛ لأن الذكر أصله حضور المذكور في قلب الذاكر ثم التعبير عن ذلك باللسان. وبعض أهل العلم يقول: يحصل ذلك الثواب لمن قال باللسان حتى ولو لم يستحضر ذلك بالقلب، والصحيح الأول لقوله ﷺ: «فإن الله لا يستجيب لعبد دعاه عن ظهر قلب غافل» [مسند أحمد، وإسناده ضعيف، وقال المناوي في هذا الحديث في «فيض القدير» 1/229: فمن زعم حسنه فضلًا عن صحته فقد جازف. ومعنى الحديث صحيح؛ إذ لا بد مع الدعاء من حضور القلب والإيقان بالإجابة، قال الإمام الرازي — فيما نقله المناوي في «فيض القدير» 1/229 —: أجمعت الأمة على أن الدعاء اللساني الخالي عن الطلب النفساني قليل النفع عديم الأثر]. وإن كان الذكر باللسان خير من السكوت، ولكن الثواب الموعود إنما لمن قالها مع حضور القلب، وكل هذه أدعية سواء كانت دعاء ثناء أو دعاء طلب، وقبول الدعاء بالثواب الموعود لا يكون عن ظهر قلب غافل، وإنما لمن استحضر بقلبه معنى ما يقول، والله أعلم.`,
        f: [
          `(ص52) على قوله «كانت علينا رعاية الإبل ... ومعناه أنهم كانوا يتناوبون رعي إبلهم ... ثم جئت إلى مجلس رسول الله ﷺ»: وهذا يدل على أن من ضمن الأسباب على التناوب على رعاية الإبل أن يتفرغوا لطلب العلم، فكان عمر بن الخطاب ﵁ مع رجل معه من الأنصار يتناوبون هذه الرعاية ليحضر كل واحد منهم مجلس رسول الله ﷺ يومًا، وهذا من الحرص على طلب العلم، وإذا فاته شيء سأل عنه أخاه، وهذا يدل على حرص الصحابة ﵃ على طلب العلم مع التكسب، وأن التكسب لا ينافي طلب العلم، ولا أن طلب العلم ينافي التكسب.`,
          `(ص53) على قوله «وقد جمع ﷺ بهاتين اللفظتين (مقبل عليهما بقلبه ووجهه) أنواع الخضوع والخشوع؛ لأن الخضوع في الأعضاء والخشوع بالقلب»: فيلزم من هذا أن تكون همة الإنسان (يقبل بوجهه) أي بهمته وإرادته، فيكون مهتمًّا بتحقيق الخشوع الباطن والظاهر في هاتين الركعتين. ولفظة القلب والوجه والاحتجاج بها بالخضوع في الأعضاء بالوجه: والظاهر والله أعلم أن الوجه المقصود به الوجهة والإرادة والهم، والإقبال بالقلب هي أعمال القلب الأخرى من النصح لله ﷻ والحب والخشية والخوف والإنابة وغير ذلك، بمعنى أن تكون همته هذه الركعات، فلا يدخل إلى الصلاة وهمه ما بعدها من أعمال الدنيا، بل الواجب أن تكون الصلاة هي الهم وهي المقصودة بذاتها، وليس أن ما بعدها أهم منها من عمل أو حتى درس علم أو غير ذلك من الأمور التي تشغل الإنسان، وهذا من أكبر ما يعين الإنسان على الخشوع في الصلاة؛ فقوله («مقبل عليهما بقلبه ووجهه») فالوجهة والإرادة هي التي يقبل بها الإنسان على صلاته بمعنى أن يهتم بها فتكون هي أكبر همه، وهكذا كان النبي ﷺ يقول: [«أرحنا بها يا بلال»]، وعن حذيفة بن اليمان ﵁ قال: «كان رسول الله ﷺ إذا حزبه أمر صلى» ((د) 1319، صحيح الجامع: 4703)، وأمور الإنسان العظمى في حياته يمتحنه ويهبه الله إياها في الصلاة كما قال ﷻ: ﴿فَنَادَتْهُ الْمَلَائِكَةُ وَهُوَ قَائِمٌ يُصَلِّي فِي الْمِحْرَابِ أَنَّ اللَّهَ يُبَشِّرُكَ بِيَحْيَى﴾، والنبي ﷺ ليلة غزوة بدر كان النبي ﷺ طول الليل يصلي، وغزوة الأحزاب وهي التي انتقل المسلمون بها من طور الدفاع إلى طور الهجوم وأصبحوا يغزون العالم فقد كان طول الليل يصلي ﷺ؛ فينبغي أن يكون أمر الصلاة أكبر هم الإنسان وأن تكون هي المقصودة لذاتها قبل غيرها من العبادات فضلًا عن الأعمال الدنيوية، وأما من يصلي لينصرف منها إلى غيرها فهذا لم ينصح النصح الكامل ولم يقبل بالقلب والوجه عليهما. نسأل الله العفو والمغفرة.`,
          `(ص53) على قوله «جئت آنفًا» أي قريبًا: وهذا من نصح عمر ﵁؛ وذلك أنه لما رآه لم يحضر الجزء الأول من الدرس فبلغه إياه، ورغبه فيه أولًا حتى يزداد رغبة في سماعه وحرصًا على حفظه ويتأكد في نفسه الاهتمام بالجملة التي قبلها.`,
        ] },
    ],
  },
  {
    title: `باب في وضوء النبي ﷺ (ص55–60)`,
    items: [
      { q: `غسل الكفين ثلاثًا عند القيام من نوم الليل: واجب أم مستحب؟`, p: `56`,
        n: `وفيه (فدعا بإناء فأكفأ منها على يديه) استحباب تقديم غسل الكفين قبل غمسهما في الإناء.`,
        o: `الإمام أحمد: يجب غسل الكفين ثلاثًا إذا قام من نومه بالليل.`,
        s: `الإمام أحمد يرى وجوب غسل الكفين ثلاثًا إذا قام من نومه بالليل، والجمهور على استحبابها في الحالتين، وظاهر الأدلة مع الإمام أحمد في القيام من النوم.` },
      { q: `صفة المضمضة والاستنشاق من كف واحدة (تكملة)`, p: `56`,
        n: `في هذا الحديث (فمضمض واستنشق من كف واحدة ففعل ذلك ثلاثًا) دلالة ظاهرة للمذهب الصحيح المختار أن السنة في المضمضة والاستنشاق أن يكون بثلاث غرفات يتمضمض ويستنشق من كل واحدة منها، وقد قدمنا إيضاح هذه المسألة والخلاف فيها في الباب الأول. وقوله في الرواية الثانية (فمضمض واستنشق واستنثر) فيه حجة للمذهب المختار الذي عليه الجماهير من أهل اللغة وغيرهم أن الاستنثار غير الاستنشاق.`,
        o: `ابن الأعرابي وابن قتيبة: الاستنثار والاستنشاق بمعنى واحد.`,
        s: `الذي ذكره هنا هو الصحيح في مشروعية الاستنشاق والمضمضة من كف واحدة صريحًا. فالاستنشاق هو سحب الماء إلى الأنف، والاستنثار هو إخراجه.` },
      { q: `أخذ الماء للوجه بيد واحدة أو باليدين جميعًا`, p: `56–57`,
        n: `قوله (ثم أدخل يده فاستخرجها فغسل وجهه ثلاثًا): هكذا وقع في صحيح مسلم [أدخل يده] بلفظ الإفراد، وكذا في أكثر روايات البخاري، ووقع في رواية للبخاري (ثم أدخل يديه فاغترف بهما)، وفي البخاري من رواية ابن عباس (ثم أخذ غرفة فجعل بها هكذا أضافها إلى يده الأخرى فغسل بها وجهه)، وفي سنن أبي داود والبيهقي من رواية علي في صفة وضوء رسول الله ﷺ (ثم أدخل يديه في الإناء جميعًا فأخذ بهما حفنة من ماء فضرب بها على وجهه)؛ فهي دالة على جواز الأمور الثلاثة وأن الجميع سنة، ويجمع بين الأحاديث بأنه ﷺ فعل ذلك في مرات. وهي ثلاثة أوجه لأصحابنا، ولكن الصحيح منها والمشهور الذي قطع به الجمهور ونص عليه الشافعي في البويطي والمزني: أن المستحب أخذ الماء للوجه باليدين جميعًا لكونه أسهل وأقرب إلى الإسباغ.`,
        o: `وجهان آخران عند الشافعية: بيد واحدة، أو بيد يضم إليها الأخرى.`,
        s: `ويحتمل أن تكون (ثم أدخل يده) للجنس — في هذا الموطن — أي [أدخل يديه]، وأن الرواية الثانية تفسر الأولى، مثلما يقول الإنسان [عملت هذا بيدي] والمقصود أنه عمله بيديه معًا، والمفرد المضاف يستعمل في العموم. فرواية (أدخل يده وضم إليها الأخرى) فهذا أكثر توصيلًا للماء وفي الإسباغ إذا جمع اليدين، أما اليد الواحدة ففيها صعوبة في إيصال الماء إلى جميع أجزاء الوجه، وإن كان يمكن ذلك بلا شك.` },
      { q: `البدء بأعلى الوجه في غسله`, p: `57`,
        n: `قال أصحابنا: ويستحب أن يبدأ في غسل وجهه بأعلاه لكونه أشرف، ولأنه أقرب إلى الاستيعاب.`,
        o: NO_O,
        s: `لأنه عندما يصب الماء على أعلى وجهه ثم ينزل الماء على باقي الأجزاء فكل ذلك غسل صحيح معتبر، خلاف ما إذا غسل أسفل الوجه أولًا ربما لا يستطيع إجراء الماء على ظاهره إلا بماء آخر، ربما يقع ذلك، فالأول أقرب إلى استيعاب الوجه. و(لكونه أشرف) لكونه موضع السجود وهو الجبهة، ولا يجزئ السجود من غير الجبهة بالاتفاق، بخلاف الأنف ففيه خلاف.` },
      { q: `مخالفة الأعضاء في عدد الغسلات، وفعل النبي ﷺ للمكروه أو ترك الأفضل لبيان الجواز`, p: `57–58`,
        n: `قوله (فغسل وجهه ثلاثًا ثم غسل يديه إلى المرفقين مرتين مرتين) فيه دلالة على جواز مخالفة الأعضاء وغسل بعضها ثلاثًا وبعضها مرتين وبعضها مرة، وهذا جائز، والوضوء على هذه الصفة صحيح بلا شك، ولكن المستحب تطهير الأعضاء كلها ثلاثًا ثلاثًا كما قدمناه، وإنما كانت مخالفتها من النبي ﷺ في بعض الأوقات بيانًا للجواز، كما توضأ ﷺ مرة مرة في بعض الأوقات بيانًا للجواز، وكان في ذلك الوقت أفضل في حقه ﷺ لأن البيان واجب عليه ﷺ. فإن قيل: البيان يحصل بالقول، فالجواب: أنه أوقع بالفعل في النفوس وأبعد من التأويل.`,
        o: NO_O,
        s: `(«كلها ثلاثًا ثلاثًا»: كما ذكرنا من قبل إلا مسح الرأس فالأصح أنه يمسح مرة واحدة كما نص في هذه الرواية: [فمسح برأسه فأقبل به وأدبر مرة واحدة]. و«مخالفتها»: أي مخالفة الصفة المستحبة.) وكذلك فعل المكروه: بأن نهى عنه ﷺ في موطن ثم فعله ﷺ في موطن، فهل نقول أن النبي ﷺ فعل المكروه؟ نقول في حقه ﷺ ليس مكروهًا، فقد نهى ﷺ عن الشرب قائمًا وزجر عنه، وهذا يدل على الكراهة لكونه ﷺ شرب قائمًا، وهذا يدل على ما ذكرنا من أنه قد يفعل المكروه في حق غيره ﷺ للبيان، ولوجود هذه المصلحة الراجحة في البيان زالت الكراهية في حقه، وذلك أن المكروه تنزيهًا إذا كان هناك مصلحة راجحة في فعله تزول الكراهية معه والله أعلم. ومن هنا كانت مخالفة النبي ﷺ لما هو أولى في بعض الأحيان أو تركه لبعض السنن لا يدل على أن المشروع دائمًا أن تترك، كما في قيام رمضان إذا عُلم السبب الذي من أجله ترك ﷺ المداومة على هذه السنة، وكونه ﷺ ترك المداومة على القيام في رمضان لا يدل على استحباب ترك المداومة على القيام في رمضان في الجماعة، فالبعض قد يُتوهم ذلك ويقول: ينبغي أن يصلي أحيانًا في بيته في رمضان ويترك الجماعة، مع كون النبي ﷺ بيَّن فضيلة شهود الجماعة وبين السبب الذي دعاه إلى عدم المواظبة على الجماعة في رمضان وهي خشية أن تفرض عليهم. وهنا وفي نحوها من الأمور عندما غسل النبي ﷺ الأعضاء مرة واحدة أو مرتين مرتين وكل ذلك ثابت، والأفضل ألا يواظب على الثلاث فلا يقال يستحب أن يغسل أحيانًا مرة — كما قد يقول بذلك البعض —؛ فالظاهر أن المستحب على الدوام أن يكون ثلاثًا، ولكن إن فعل أجزأ، وأيضًا قد يكون مستحبًّا فيمن يُعلِّم غيره أن الوضوء مرة مرة يجزئ، أو كان هناك مصلحة راجحة أخرى تجعل ترك الأفضل هنا مشروعًا أو غيره أولى منه، والله أعلم.` },
      { q: `صفة مسح الرأس (الإقبال والإدبار) ورد اليدين لمن لا شعر له أو كان شعره مضفورًا`, p: `58–59`,
        n: `قوله (فمسح برأسه فأقبل بيديه وأدبر): هذا مستحب باتفاق العلماء؛ فإنه طريق إلى استيعاب الرأس ووصول الماء إلى جميع شعره. قال أصحابنا: وهذا الرد إنما يستحب لمن كان له شعر غير مضفور، أما من لا شعر على رأسه أو كان شعره مضفورًا فلا يستحب له الرد إذ لا فائدة فيه، ولو رد في هذه الحالة لم يحسب الرد مسحة ثانية لأن الماء صار مستعملًا بالنسبة إلى ما سوى تلك المسحة. وليس في هذا الحديث دلالة لوجوب استيعاب الرأس بالمسح؛ لأن الحديث ورد في كمال الوضوء لا فيما لا بد منه.`,
        o: `الشافعية: لا يُستحب الرد لمن لا شعر له أو كان شعره مضفورًا.`,
        s: `هذا الكلام فيه نظر، بل الظاهر والله أعلم أنه يستحب الرد عمومًا لأنه فعل النبي ﷺ، ومسألة أنها أكمل في الاستيعاب كافية، وقد بين ابن قدامة في (المغني) في كيفية المسح: [والمستحب في مسح الرأس أن يبل يديه ثم يضع طرف إحدى سبابتيه على طرف الأخرى ويضعهما على مقدم رأسه، ويضع الإبهامين على الصدغين، ثم يمر يديه إلى قفاه، ثم يردهما إلى الموضع الذي بدأ منه؛ كما روى عبد الله بن زيد في وصف وضوء رسول الله ﷺ قال: «فمسح رأسه بيديه، فأقبل بهما وأدبر، بدأ بمقدم رأسه حتى ذهب بهما إلى قفاه، ثم ردهما إلى المكان الذي بدأ منه» متفق عليه]. والصدغ هي العظمة التي هي أمام الأذن والتي هي بداية الوجه من أسفلها وبداية الرأس من أعلاها، فلكي يستوعب هذا الجزء الذي ينساه كثير من الناس فلا يهتم باستيعابه فيجعل الإبهام على هاتين العظمتين، وذلك حتى يستوعب جميع الرأس بالمسح، فهناك قول بوجوب الاستيعاب وهو قول الإمام أحمد ومالك، وذلك حتى يكون قد توضأ وضوءًا مجزئًا بالاتفاق كما ذكرنا، يجب عليه مسح الرأس كله ويتحقق ذلك بما ذكرنا. وقوله [لم يحسب الرد مسحة ثانية] لأن الشافعية يقولون باستحباب المسح ثلاثًا؛ فقد جاء في (المغني): [ويحتمله كلام الخرقي لقوله: الثلاث أفضل، وهو مذهب الشافعي، وروي عن أنس، قال ابن عبد البر: كلهم يقول: مسح الرأس مسحة واحدة. وقال الشافعي: يمسح برأسه ثلاثًا؛ لأن أبا داود روى عن شقيق بن سلمة قال: رأيت عثمان بن عفان غسل ذراعيه ثلاثًا، ومسح برأسه ثلاثًا، ثم قال: رأيت رسول الله ﷺ فعل مثل هذا]. وأما استيعاب الرأس بالمسح فقد ذكرنا الخلاف في هذه المسألة.`, },
      { q: `الماء المستعمل: هل تصح به الطهارة؟ وأخذ ماء جديد للرأس والأذنين`, p: `60`,
        n: `قوله (ومسح برأسه بماء غير فضل يده): معناه أنه مسح الرأس بماء جديد لا ببقية ماء يديه، ولا يستدل بهذا على أن الماء المستعمل لا تصح الطهارة به؛ لأن هذا إخبار عن الإتيان بماء جديد للرأس، ولا يلزم من ذلك اشتراطه.`,
        o: `الشافعية: الماء المستعمل طاهر غير طهور لا تصح الطهارة به (وهو مذهب النووي). ومالك: الماء المستعمل باقٍ على طهوريته ويجوز استعماله.`,
        s: `الإمام النووي رحمه الله رغم أن مذهبه عدم صحة الطهارة بالماء المستعمل لأنه صار طاهرًا غير طهور، إلا أنه بيَّن أن الاستدلال بهذا الحديث على هذه المسألة غير صحيح، وإنما يحتاج الأمر إلى دليل آخر؛ لأن الحديث فعل، والفعل لا يدل على عدم إجزاء غيره [نعم هو فعل ذلك، ولكن هل يلزم أن غيره لا يجزئ؟ لا يلزم لأنه قد يكون هذا الفعل هو المستحب (الفعل يدل على الاستحباب ولا يدل دائمًا على اللزوم فضلًا عن الشرطية)]. والصحيح أن الماء المستعمل تصح به الطهارة وأنه ما زال طهورًا استصحابًا للأصل حيث أنه كان طهورًا، ولم يأت دليل ناقل، والأدلة التي احتجوا بها — سيأتي الكلام عليها — ليست صريحة في كونه ينتقل من كونه طهورًا إلى طاهر فقط، والصحيح أن الماء المطلق طالما سُمي ماءً فهو طهور كما خلقه الله ﷻ. وقول مالك في هذه المسألة أصح الأقوال، وهو أن الماء المستعمل باقٍ على طهوريته ويجوز استعماله، وإن كان عدم ورود ما يدل على أن الصحابة كانوا يجمعون ما تساقط من الأطراف بعد الوضوء لم يُنقل لعدم الحاجة إليه، ولوجود المشقة البالغة في جمعه ثم إعادة استعماله، وللتنزه عن ذلك لوجود بعض الأدران التي وإن لم تمنع الطهارة إلا أنها يستقذرها الإنسان، ولكمال الطهارة وذلك يحصل باستعمال الماء الجديد، كما أن هذا الماء الذي أخذه للرأس كان ماءً جديدًا وذلك لتحقيق الكمال في هذه المسألة، ولكن لا يلزم من ذلك وجوب أخذ ماء جديد للرأس. والظاهر أن ماء الأذنين هو نفس ماء الرأس؛ لأنه قال: (ومسح برأسه بماء غير فضل يده) دليل على أنه أخذ لرأسه ماءً جديدًا، والأذنان من الرأس، فالظاهر أنه يمسح الأذنين بنفس ماء الرأس لأنهما منه، ولم يذكر أنه أخذ لهما ماءً جديدًا — في هذا الحديث —.` },
    ],
  },
  {
    title: `باب الإيتار في الاستنثار والاستجمار (ص61–64)`,
    items: [
      { q: `معنى الاستجمار والإيتار فيه، وحكم الإنقاء والعدد`, p: `61–63`,
        n: `أما الاستجمار فهو مسح محل البول والغائط بالجمار وهي الأحجار الصغار. قال العلماء: يقال الاستطابة والاستجمار والاستنجاء لتطهير محل البول والغائط، فأما الاستجمار فمختص بالمسح بالأحجار، وأما الاستطابة والاستنجاء فيكونان بالماء ويكونان بالأحجار. هذا الذي ذكرناه من معنى الاستجمار هو الصحيح المشهور الذي قاله الجماهير. وقال القاضي عياض: اختلف قول مالك وغيره في معنى الاستجمار المذكور في هذا الحديث فقيل هذا، وقيل: المراد به في البخور أن يأخذ منه ثلاث قطع أو يأخذ منه ثلاث مرات يستعمل واحدة بعد أخرى، قال: والأول أظهر. والمراد بالإيتار أن يكون عدد المسحات ثلاثًا أو خمسًا أو فوق ذلك من الأوتار، ومذهبنا أن الإيتار فيما زاد على الثلاث مستحب، وحاصل المذهب أن الإنقاء واجب واستيفاء ثلاث مسحات واجب، فإن حصل الإنقاء بثلاث فلا زيادة، وإن لم يحصل وجب الزيادة، ثم إن حصل بوتر فلا زيادة، وإن حصل بشفع كأربع أو ست استُحب الإيتار. وقال بعض أصحابنا: يجب الإيتار مطلقًا لظاهر هذا الحديث. وحجة الجمهور الحديث الصحيح في السنن أن رسول الله ﷺ قال: «من استجمر فليوتر، من فعل فقد أحسن، ومن لا فلا حرج»، ويحملون حديث الباب على الثلاث وعلى الندب فيما زاد.`,
        o: `قيل: المراد بالاستجمار في الحديث البخور. وبعض الشافعية: يجب الإيتار مطلقًا.`,
        s: `(الإيتار: هو استعمال حصوات وتر أو غسلات وتر. والاستنثار: هو خروج الماء من الأنف، وهو ملازم للاستنشاق فلن يكون هناك استنثار إلا إذا كان هناك استنشاق. والاستطابة: هو طلب أن يكون الموضع طيبًا طاهرًا.) أي أن الاستجمار هو استعمال الأحجار في إزالة أثر البول والغائط. والصحيح المعروف ما قدمناه: أن معنى الحديث هنا أنه [إذا استجمر أحدكم فليستجمر وترًا] معناه أنه إذا استنجى أو استطاب أو أزال أثر الغائط. وقوله (الإنقاء واجب واستيفاء ثلاث مسحات واجب) بمعنى أنه لو مسح بحجر واحد وقد أنقى فحصل منه النقاء، فلا بد أن يمسح إلى ثلاث مسحات، والإنقاء واجب بمعنى أنه ولو زاد على ثلاث، فلو لم يحدث نقاء من أثر البول والغائط إلا بأربع مسحات وجب أن يستعمل أربع مسحات، فكلا الأمرين واجب: الإنقاء واستيفاء الثلاث مسحات. (فلا زيادة) أي لم تشرع الزيادة. والحديث [من استجمر فليوتر] والواجب إزالة النجاسة بثلاث مسحات على الأقل. والحديث الذي في السنن ضعيف؛ كثير جدًّا من مسائل الآداب الآتية الجمهور يحملها على الندب ويكون ظاهر الأمر الوجوب، وهذا الباب يكثر السؤال فيه كثيرًا جدًّا منه أنه ليس له صارف صحيح أو صريح إلى الاستحباب، فأتوقف في مثل هذه المسائل وأقول بمشروعية الالتزام بظاهر الأوامر، فلا نجزم بالاستحباب كقول الجمهور ولا أتجرأ بالقول بالوجوب كقول الظاهرية وقلة من الشافعية؛ فلو كان هناك اتفاق لقلنا به، لكن كثير من المسائل الأدلة فيها ظاهرة في الوجوب مثل الأكل باليمين مع كونه ينصون على استحبابه، لكن ظاهر الحديث الوجوب بقوة، فبعض المسائل الأمر فيها لا يكون بنفس الدرجة من القوة؛ فحديث الأكل باليمين قال له: [«كل بيمينك»، قال: لا أستطيع، قال: «لا استطعت»، ما منعه إلا الكبر، قال: فما رفعها إلى فيه] مسلم، فدعا عليه، وذلك لا يكون إلا لترك واجب. فليس الكل مثل هذه المنزلة، فنقول بمشروعية الالتزام وتأكيد الالتزام بالأمر النبوي ونتوقف في الإيجاب والاستحباب، وخاصة أنه لم ينقل عن الصحابة تصريح بالوجوب أو الاستحباب، بل نقل عنهم الفعل والأمر دون التصريح بالتحريم أو الإيجاب أو الكراهة أو الاستحباب، والله أعلم. إلا ما بيناه تفصيلًا من وجود الصارف الواضح؛ فلو صح الحديث الذي ذكره في السنن لكان صريحًا في الصرف من الوجوب إلى الاستحباب، لكن كما ذكرنا هو حديث ضعيف.` },
      { q: `حكم الاستنثار والاستنشاق، وصارف الأمر فيهما`, p: `63–64`,
        n: `وأما قوله ﷺ «فليجعل في أنفه ماء ثم لينثر» ففيه دلالة ظاهرة على أن الاستنثار غير الاستنشاق، وأن الانتثار هو إخراج الماء بعد الاستنشاق مع ما في الأنف من مخاط وشبهه. وفيه دلالة لمذهب من يقول الاستنشاق واجب لمطلق الأمر، ومن لم يوجبه حمل الأمر على الندب بدليل أن المأمور به حقيقة وهو الانتثار ليس بواجب بالاتفاق، فإن قالوا: ففي الرواية الأخرى (إذا توضأ فليستنشق بمنخريه من الماء ثم لينتثر) فهذا فيه دلالة ظاهرة للوجوب، لكن حمله على الندب محتمل ليجمع بينه وبين الأدلة الدالة على الاستحباب.`,
        o: `من يوجب الاستنشاق لمطلق الأمر (الحنابلة وغيرهم).`,
        s: `أن الانتثار مأمور به، وهذا الكلام غير ظاهر؛ لأنه إذا كان هذا غير واجب بالاتفاق فهذا هو الصارف أي الإجماع، ولكن تبقى الأوامر (فليستنشق، فليجعل في أنفه ماء) فما هو الصارف في هذا؟ ولكن نقول: إن هذا في الحقيقة دليل ضعيف على صرف الأمر، والأحسن منه — وقد قدمنا أن الاستنشاق على الراجح أنه مستحب — ما ذكرنا من أن حديث المسيء صلاته الذي ورد فيه الوضوء كما أمره الله ﷻ فإنه لم يزد على ما في الآية، والآية في مقام البيان [لم ترد على الأعضاء الأربعة] وتعليم الجاهل وهو تعليم ما لا بد منه ولا يجوز تأخير البيان عن وقت الحاجة، والنبي ﷺ لم يزد على ما في الآية، ومن هنا قلنا أن واجبات الوضوء هو ما في الآية فقط، ولكن أمر النبي ﷺ تأكيد للاستحباب. ومن قال إن غسل الوجه دخل فيه المضمضة والاستنشاق قلنا له هذا خلاف الظاهر، فالأحاديث فيها [تمضمض واستنشق وغسل وجهه] والواو عطف على المغايرة، والوجه هو ما يواجه به وليس هو باطن الوجه؛ فالاستنشاق غسل باطن الوجه وهو الأنف، والمضمضة غسل باطن الفم، والواجب غسل الظاهر الذي يواجه به فهو الوجه وليس الباطن، وعلى هذا وإن كان ظاهر الأمر الوجوب إلا أن الصارف الأمر ما ذكرنا. ولذلك قلنا أن الكلام الأول غير ظاهر؛ لأن الرواية الأخرى صريحة في الأمر بالاستنشاق، ولذلك رواية (فلينتثر) ليست دالة على عدم وجوب الاستنشاق، والدلالة على عدم وجوب الاستنشاق والمضمضة الأدلة الخارجية.` },
      { q: `معنى «فإن الشيطان يبيت على خياشيمه» والاستنثار عند الاستيقاظ من النوم`, p: `64–65`,
        n: `قال العلماء: الخيشوم أعلى الأنف، وقيل: هو الأنف كله، وقيل: هي عظام رقاق لينة في أقصى الأنف بينه وبين الدماغ، وقيل غير ذلك، وهو اختلاف متقارب المعنى. قال القاضي عياض رحمه الله تعالى: يحتمل أن يكون قوله ﷺ «فإن الشيطان يبيت على خياشيمه» على حقيقته؛ فإن الأنف أحد منافذ الجسم التي يُتوصل إلى القلب منها لا سيما وليس من منافذ الجسم ما ليس عليه غلق سواه وسوى الأذنين، وفي الحديث: «إن الشيطان لا يفتح غلقًا»، وجاء في التثاؤب الأمر بكظمه من أجل دخول الشيطان حينئذ في الفم. قال: ويحتمل أن يكون على الاستعارة؛ فإن ما ينعقد من الغبار ورطوبة الخياشيم قذارة توافق الشيطان.`,
        o: `القاضي عياض (احتمال ثانٍ): أنه على الاستعارة.`,
        s: `(الخيشوم: الأشهر أنه أعلى الأنف.) الاحتمال الأول هو الصحيح بل الصواب؛ فليس هناك ما يدفعنا إلى تأويل الكلام، فإن النبي ﷺ قال: [«فإن الشيطان يبيت على خياشيمه»]، فإن الشيطان للإنسان بالمرصاد، وهو يدل على شدة حرصه على إضلال الإنسان واستغلاله أي فرصة للفتور عن ذكر الله حتى يتمكن من الدخول فيجري منه مجرى الدم ليتمكن من الوسوسة، وهذا يدل على مخالطة الشيطان للإنسان في أنه ينتظر الدخول ليجري منه مجرى الدم، وهذا ليس بمستبعد. وهل يكون بذلك كل إنسان ملبوسًا؟ لا، بل اللبس هو أن يصرعه الشيطان فيغلبه على عقله، أما أنه يجري منه مجرى الدم — فالشيطان مخلوق من النار وذوبان الغازات في دم الإنسان أمر دل عليه العلم الحديث وخروجها منه مرة أخرى، فالأكسجين يدخل ثم يخرج وهكذا — فما المانع من أن يحمل هذا الكلام على ظاهره، فالشيطان يجري في الإنسان مجرى الدم حقيقة وليست استعارة، فيلازمه من غير أن يصرعه ولكن يوسوس، والوسوسة تكون بوصوله عن طريق الدم إلى الأماكن التي يجعله يفكر فيها من المعاني السيئة والأمور المنكرة، فنحن نثبت هذا، والشيطان يكره الماء ويكره نظافة الإنسان ويكره الوضوء. وهذا الاستنثار عند الاستيقاظ من النوم أمر مستقل عن الوضوء بمعنى أنه إذا استيقظ فاستنثر مع وضوئه فيها وإلا فليستنثر مجردًا، وهذا أمر تعبدي غير مدرك المعنى بالأسباب الظاهرة، ومبيت الشيطان أمر غيبي، ولذا كان الوجوب في هذا الأمر هو الظاهر، وهذا غير متعلق بالوضوء بل في نوم الليل لقوله (يبيت). والظاهر والله أعلم أن هذا الاحتمال وارد أيضًا في غسل اليدين أنه تعبدي في القيام من نوم الليل؛ فإذا كان الشيطان يبيت على الخياشيم فإنه يبيت على اليد أيضًا لكي يتمكن من إضلال الإنسان فيما يعمل بيده؛ لأن قول النبي ﷺ: («فإنه لا يدري أين باتت يده») فيحتمل أن يكون الشيطان متربصًا ليده، فإذا غسلها الإنسان زال عنه أثر مبيت الشيطان، فظاهر الأمر الوجوب. والشيطان هو القرين الذي يبيت على الخياشيم فهو جالس متى يستطيع الدخول للوسوسة، وهذا دليل على أن وسوسته تقل جدًّا بالوضوء وربما تنعدم، فكلما كان على طهارة كلما عجز الشيطان عن الدخول، والدخول أثناء التثاؤب لذلك يكظم ما استطاع، فإن عجز فليضع يده على فمه لكي يمنع من دخول الشيطان حتى لا يستطيع الوسوسة. ولذلك يمكن أن نقول أن هناك بعض من الأمراض النفسية التي فيها وسوسة يمكن استعمال المواد الكيماوية في علاجها، وهو أمر مشهور وقد أصبح معلومًا؛ فهناك بعض الأدوية فيها مواد كيماوية تقلل بعض أمراض الوسوسة كالوسواس القهري، فالعلاجات الكيميائية تؤثر فيه تأثيرًا ظاهرًا جدًّا، فما المانع؟ فبعض الناس يقول: ما العلاقة بين الوسوسة وبين الدواء والمواد الكيماوية؟ فهذا الأمر وارد، فإن الأفكار الإنسانية إلى الآن فإن الإنسان عاجز عن معرفة كيف يحدث له فكر في شيء معين، ولكن هي عبارة عن تفاعلات معينة تقع في مخ الإنسان وتنتقل منها إلى القلب وغير ذلك، وتجري في الدم تثير غرائز معينة وتجري إلى الأعصاب تثير شهوات معينة بمجرد التفكير، فهناك أشياء خفية كثيرة جدًّا، فما المانع من أن يكون هناك أدوية أو مواد كيماوية تضاد ما يتسبب الشيطان في وجوده في الإنسان؛ فالإنسان يمتثل أوامر الشرع ويأخذ بالأسباب الظاهرة القدرية والشرعية، فإذا ثبت وجود مثل هذه الأدوية فهذا أمر غير مستبعد.` },
    ],
  },
];
